import type { Chapter } from '../../types'

// RES5 fact bank. Authored from the official RES5 study text (1st Ed v1.1,
// Dec 2024), grounded strictly in the ebook across all 27 chapters.
export const res5Chapters: Chapter[] = [
  {
    id: 'r1',
    num: 1,
    title: 'Financial Advisers Act And Financial Advisers Regulations - Financial Advisers And Representatives',
    page: 12,
    concepts: [
      { id: 'r1-01', term: 'FAA and FAR framework', fact: 'The Financial Advisers Act (FAA) came into force on 1 October 2002 and, together with the Financial Advisers Regulations (FAR), is administered by MAS. It regulates financial advisers and their representatives in Singapore.', trap: 'The FAA is administered by MAS, not by the Singapore College of Insurance or the Ministry of Finance.' },
      { id: 'r1-02', term: 'Four principles of the FAA and FAR', fact: 'The FAA and FAR are built on four principles: protecting customers\' interests, consistency of regulation across similar activities, accountability of financial advisers for their representatives, and safeguarding independence of advice.', trap: 'Profit maximisation for the industry is not one of the principles - the focus is on fair dealing and customer protection.' },
      { id: 'r1-03', term: 'Need for a financial adviser\'s licence', fact: 'Under Section 6(1), no person may act as a financial adviser in Singapore without a financial adviser\'s licence unless exempt. Only a corporation may apply for the licence. Section 18(1) prohibits holding out as a licensed financial adviser without a licence, and Section 6(2) deems certain conduct targeted at the Singapore public as acting in Singapore.', trap: 'Individuals and partnerships cannot hold a financial adviser\'s licence - only corporations can.' },
      { id: 'r1-04', term: 'Exempt financial advisers - Section 20(1)', fact: 'Section 20(1) exempts certain institutions from holding a financial adviser\'s licence, including banks, merchant banks, insurance companies and registered insurance brokers, finance companies and holders of a capital markets services licence. They remain subject to FAA conduct of business rules.', trap: 'Exempt financial advisers are exempt from licensing only - they must still comply with the conduct requirements of the FAA and its Notices.' },
      { id: 'r1-05', term: 'Excluded persons - First Schedule', fact: 'The First Schedule to the FAA excludes certain persons from the definition of financial adviser, such as lawyers, accountants and journalists who give advice that is incidental to their profession, and persons who merely publish periodicals available to the public.', trap: 'The exclusion applies only where the advice is incidental to the person\'s main profession or business - it is lost if advising becomes a distinct service.' },
      { id: 'r1-06', term: 'Financial advisory services - Second Schedule', fact: 'The Second Schedule lists the financial advisory services: advising others concerning investment products (directly or through publications), issuing or promulgating research analyses or reports on investment products, marketing of any collective investment scheme, and arranging of any contract of insurance in respect of life policies (other than reinsurance).', trap: 'Arranging general insurance is not a financial advisory service - only arranging life policies is covered.' },
      { id: 'r1-07', term: 'Investment products under the FAA', fact: 'Investment products include securities, units in collective investment schemes, life policies and certain derivatives contracts. Structured deposits were prescribed as investment products with effect from 2 December 2005.', trap: 'Ordinary bank deposits and general insurance policies are not investment products under the FAA.' },
      { id: 'r1-08', term: 'Licence application and maintenance', fact: 'A corporation applies to MAS for a financial adviser\'s licence and must meet minimum financial requirements under Regulation 15 and maintain professional indemnity insurance. Since 26 November 2010, licences no longer need periodic renewal and remain valid until revoked, suspended or surrendered.', trap: 'There is no annual renewal of the financial adviser\'s licence since 26 November 2010 - it continues in force until it is revoked, suspended or surrendered.' },
      { id: 'r1-09', term: 'Exempt persons under Regulation 27(1)(d)', fact: 'Regulation 27(1)(d) exempts a person who provides financial advisory services concerning investment products (other than life policies) to not more than 30 accredited investors. Such exempt persons must be fit and proper and must not represent that they are licensed by MAS.', trap: 'The 30 accredited investors cap excludes life policies - advice on life policies cannot rely on this exemption.' },
      { id: 'r1-10', term: 'Accredited investor thresholds', fact: 'An individual is an accredited investor if his net personal assets exceed S$2 million (with limits on counting the primary residence), his net financial assets exceed S$1 million, or his income in the preceding 12 months is not less than S$300,000. A corporation qualifies with net assets exceeding S$10 million.', trap: 'The income test is S$300,000 over the preceding 12 months, not per calendar year average, and the corporate test is S$10 million net assets, not revenue.' },
      { id: 'r1-11', term: 'Restricted use of titles', fact: 'Under Section 17, only licensed or exempt financial advisers may use the titles \'financial adviser\' or \'life insurance broker\'; contravention attracts a fine up to S$12,500 and S$1,250 per day for a continuing offence. Regulation 21 restricts use of \'independent\' to advisers who receive no commission or benefit that creates product bias, operate without restrictions on the products they recommend, and have no conflict of interest from connections with product providers.', trap: 'A financial adviser paid commissions by product providers generally cannot call itself \'independent\' under Regulation 21.' },
      { id: 'r1-12', term: 'Representative notification and public register', fact: 'Since 26 November 2010 the Representative Notification Framework applies: principals lodge documents with MAS and appointments are entered in the public register of representatives under Section 73. MAS may refuse an appointment under Section 30 on grounds such as undischarged bankruptcy, unsatisfied judgment debts, compromise with creditors, or conviction involving fraud or dishonesty. Appeals against MAS decisions go to the Minister within 30 days and the Minister\'s decision is final.', trap: 'Appeals are made to the Minister within 30 days, not to the courts, and the Minister\'s decision is final.' },
      { id: 'r1-13', term: 'One-principal rule - Section 27(1)', fact: 'An appointed, provisional or temporary representative may act for only one principal, unless otherwise approved by MAS in writing or where the principals are related corporations. Contravention attracts a fine up to S$25,000 or imprisonment up to 12 months or both, with S$2,500 per day for a continuing offence.', trap: 'There are two exceptions to the one-principal rule: MAS written approval and related corporations - not just related corporations.' },
      { id: 'r1-14', term: 'Representative offences and false statements', fact: 'Acting as a representative without being appointed attracts under Section 22(8) a fine up to S$25,000 or imprisonment up to 12 months or both, plus S$2,500 per day for a continuing offence. A principal that permits an unappointed person to act is liable under Section 22(9) to a fine up to S$50,000 plus S$5,000 per day. Under Section 32(1), making a false or misleading statement to MAS in connection with an appointment attracts a fine up to S$50,000, with a defence of having made all reasonable inquiries.', trap: 'The principal\'s penalty for permitting an unappointed representative (S$50,000 plus S$5,000 per day) is double the individual\'s penalty.' },
      { id: 'r1-15', term: 'Appointed representative requirements', fact: 'An appointed representative must be at least 21 years old, satisfy fit and proper criteria and have his appointment entered in the public register. Under Regulation 8A the representative must commence business within 6 months of appointment, and the principal must notify MAS of cessation within 1 month. Changes in particulars must be notified no later than the next business day under Regulation 12A, cessation is reported via Form 18 within 14 days, and records must be kept for 5 years.', trap: 'Do not confuse the timelines: 6 months to commence business, 1 month to notify cessation of business, next business day for changes in particulars, and 14 days for Form 18.' },
      { id: 'r1-16', term: 'Provisional representatives', fact: 'A provisional representative is an individual licensed or regulated for equivalent activities overseas for a continuous period of 12 months (and who ceased not more than 12 months before), allowed to act for up to 3 months while completing CMFAS exams. He gives a one-time notification via Form 3D after passing all exams, and his principal gives undertakings that he will be accompanied at client meetings, copy his supervisor on client emails, and not communicate with clients by telephone unaccompanied.', trap: 'Provisional representative status lasts at most 3 months and cannot be extended by simply reapplying.' },
    ],
  },
  {
    id: 'r2',
    num: 2,
    title: 'Financial Advisers Act And Financial Advisers Regulations - Conduct Of Business, Powers Of Authority And Offences',
    page: 47,
    concepts: [
      { id: 'r2-01', term: 'Disclosure of product information - Section 34', fact: 'Section 34(1) requires a licensed financial adviser to disclose, to every client and prospective client, all material information relating to any designated investment product it recommends, including the terms and conditions, benefits and risks, and fees and charges.', trap: 'Disclosure must cover material information on risks and charges, not just the benefits of the product.' },
      { id: 'r2-02', term: 'False or misleading statements - Section 35', fact: 'Section 35 prohibits a licensed financial adviser from making false or misleading statements, or deceptive or manipulative acts, in connection with providing financial advisory services. The penalty is a fine up to S$50,000 or imprisonment up to 12 months or both.', trap: 'Liability can arise from omitting material facts that make a statement misleading, not only from actively false claims.' },
      { id: 'r2-03', term: 'Reasonable basis for recommendations - Section 36', fact: 'Section 36 requires a licensed financial adviser to have a reasonable basis for recommendations, taking into account the client\'s investment objectives, financial situation and particular needs. Under Section 36(3), a client who suffers loss because this duty was breached may recover damages through civil action.', trap: 'Section 36 gives the client a civil remedy in damages - it is not solely a matter of regulatory penalty.' },
      { id: 'r2-04', term: 'Client\'s money and property - Section 37', fact: 'Under Section 37 and related regulations, a licensed financial adviser must handle client\'s money and property as prescribed. A lien or claim on client\'s property is void unless it is for fees, charges or other amounts properly due, and any charge or mortgage over client\'s money or property is void.', trap: 'An adviser cannot pledge or mortgage client assets to secure its own borrowings - such a charge is void.' },
      { id: 'r2-05', term: 'Insurance broking premium accounts - Section 41 and Regulation 20', fact: 'A licensed financial adviser carrying on insurance broking must keep premium moneys in a separate insurance broking premium account with a bank. Withdrawals are permitted only for prescribed purposes such as paying insurers or refunding clients, and moneys in the account are not available to the adviser\'s other creditors.', trap: 'Premium account moneys cannot be used for the adviser\'s working capital - withdrawals are limited to prescribed purposes.' },
      { id: 'r2-06', term: 'Placement with unlicensed insurers - Section 42', fact: 'Section 42 prohibits a licensed financial adviser from negotiating or placing risks with unlicensed insurers, except for reinsurance, risks outside Singapore, or where MAS permits placement of an exceptional risk that cannot be placed with licensed insurers.', trap: 'The exceptions are narrow: reinsurance, offshore risks and MAS-permitted exceptional risks - client consent alone does not allow use of an unlicensed insurer.' },
      { id: 'r2-07', term: 'Representations about insurance proposals - Section 43', fact: 'Section 43 makes it an offence for a licensed financial adviser to make false or misleading representations concerning insurance proposals or claims. The penalty is a fine up to S$25,000 or imprisonment up to 12 months or both.', trap: 'This offence targets representations about proposals and claims in insurance broking - its penalty (S$25,000 or 12 months) is lower than the Section 35 penalty.' },
      { id: 'r2-08', term: 'Disclosure of interests in circulars - Section 45', fact: 'Under Section 45, a licensed financial adviser sending a circular or written communication making a recommendation on Specified Products must include a concise statement of any interest it or its associated persons have in those products. A defence exists under Section 45(2) for those who merely distribute in the ordinary course of business without knowledge. The penalty is a fine up to S$25,000 or imprisonment up to 12 months.', trap: 'The interest disclosure duty in Section 45 applies to written circulars and communications recommending Specified Products, not to every verbal recommendation.' },
      { id: 'r2-09', term: 'Register of interests in Listed Specified Products - Regulations 20A and 20B', fact: 'A licensed financial adviser and its representatives who advise on Listed Specified Products must maintain a register of their interests in such products, enter changes within 7 days, and retain entries for 5 years. The register is kept at the principal place of business (for an individual) or a place of business in Singapore (for a corporation), and may be electronic if MAS is given full access.', trap: 'Changes in interests must be entered in the register within 7 days, and each entry retained for 5 years - do not swap the two figures.' },
      { id: 'r2-10', term: 'Unsecured loans to officers - Regulation 18', fact: 'Regulation 18 prohibits a licensed financial adviser from granting unsecured loans or unsecured credit facilities exceeding S$3,000 in aggregate to any of its directors who are not employees, or officers, employees or representatives. For this purpose, a loan to a director includes loans to the director\'s family members, and security is measured at market value.', trap: 'The S$3,000 cap is an aggregate per person including family members - splitting a larger loan into small pieces still breaches the cap.' },
      { id: 'r2-11', term: 'Appointment of CEO and directors - Sections 63 and 64', fact: 'Under Section 63(1), a licensed financial adviser must obtain prior MAS approval (application via Form 11) before appointing a chief executive officer or director; MAS assesses criteria under Regulation 13(2). Under Section 64(1), MAS may direct the removal of an officer who fails the fit and proper test.', trap: 'MAS approval must be obtained before the CEO or director is appointed, not notified after the appointment.' },
      { id: 'r2-12', term: 'MAS supervisory powers - directions and prohibition orders', fact: 'MAS may issue written directions under Section 67(1) and prohibition orders under Section 68 against persons who contravene the FAA or are otherwise unfit. Employing a person known to be subject to a prohibition order attracts under Section 69(2) a fine up to S$50,000. Orders may be varied or revoked under Section 70, and an aggrieved person may appeal to the Minister within 30 days.', trap: 'A prohibition order restricts the person from conducting regulated activities - and their would-be employer commits an offence by knowingly employing them.' },
      { id: 'r2-13', term: 'Corporate offenders and falsification - Sections 111 to 113', fact: 'Where a corporation commits an offence, officers who consented, connived or were negligent may also be prosecuted under Section 111. An officer who fails to secure compliance is liable under Section 112(1) to a fine up to S$100,000 or imprisonment up to 2 years. Falsification of records under Section 113(1) attracts the same maximum penalty of S$100,000 or 2 years.', trap: 'Officers can be personally liable for the company\'s offence through consent, connivance or neglect - incorporation does not shield them.' },
    ],
  },
  {
    id: 'r3',
    num: 3,
    title: 'MAS Notices - Part I [Notice Nos: FAA-N16; FAA-N03 And FAA-N11]',
    page: 69,
    concepts: [
      { id: 'r3-01', term: 'FAA-N16 scope and effect', fact: 'The Notice on Recommendations on Investment Products (FAA-N16) took effect on 1 January 2012 and sets requirements for recommendations, including the Customer Knowledge Assessment and Customer Account Review for Specified Investment Products (SIPs). For CKA and CAR purposes, \'client\' means a natural person only.', trap: 'CKA and CAR apply to natural persons - corporate clients are not assessed under these requirements.' },
      { id: 'r3-02', term: 'Customer Knowledge Assessment (CKA)', fact: 'Before recommending an unlisted SIP, the financial adviser must conduct a CKA. A client has the relevant knowledge or experience if he has a diploma or higher qualification in a listed field, a professional finance qualification, at least 6 transactions in unlisted SIPs (such as CIS or ILPs) in the preceding 3 years, or at least 3 consecutive years of relevant working experience in the past 10 years.', trap: 'The transaction test requires 6 transactions within the preceding 3 years - not 3 transactions in 6 years.' },
      { id: 'r3-03', term: 'Validity of CKA and CAR', fact: 'A CKA outcome is valid for 1 year from the assessment. A CAR outcome is valid for 3 years, or continues where the client has transacted in listed SIPs at least once in each subsequent 3-year period.', trap: 'CKA validity (1 year) is shorter than CAR validity (3 years) - do not swap them.' },
      { id: 'r3-04', term: 'Customer Account Review (CAR)', fact: 'Before a client opens an account to trade listed SIPs, the intermediary must conduct a CAR using criteria similar to the CKA, including whether the client has executed at least 6 transactions in listed SIPs in the preceding 3 years.', trap: 'CAR is for listed SIPs and CKA for unlisted SIPs - the assessments are not interchangeable.' },
      { id: 'r3-05', term: 'Client who fails CKA or CAR', fact: 'If a client is assessed not to have the relevant knowledge or experience, the financial adviser must inform the client of the outcome and offer to provide advice. If the client still wishes to proceed without a recommendation, approval from senior management (or a designated person under a board-approved written framework) is required, and the transaction cannot proceed on an execution-only basis.', trap: 'A client who fails the CKA cannot simply sign a waiver and transact execution-only - senior management approval and an offer of advice are required.' },
      { id: 'r3-06', term: 'Deemed outcome and joint transactions', fact: 'Where a client declines to provide the information needed for the CKA or CAR, the financial adviser must treat the client as not possessing the relevant knowledge or experience. For joint transactions, each client is assessed individually.', trap: 'Refusing to provide information leads to a deemed fail - not a deemed pass or an exemption from assessment.' },
      { id: 'r3-07', term: 'Documentation and switching', fact: 'The financial adviser must document the basis for each recommendation and maintain records of CKA and CAR outcomes. Where a client switches products, the adviser must disclose whether the switch is disadvantageous, considering factors such as new charges incurred and benefits lost.', trap: 'Product switching requires specific disclosure of potential disadvantages such as fresh charges - it is not treated like a first-time purchase.' },
      { id: 'r3-08', term: 'Overseas-listed investment products risk warning', fact: 'For a client transacting in an overseas-listed investment product for the first time on or after 8 October 2018, the intermediary must provide the prescribed risk warning statement and obtain the client\'s acknowledgement, keeping the acknowledgement for not less than 5 years.', trap: 'The risk warning acknowledgement is needed for the first transaction on or after 8 October 2018 and must be retained for at least 5 years.' },
      { id: 'r3-09', term: 'Penalty for breach of a MAS Notice', fact: 'Under Section 58(5) of the FAA, contravening a MAS Notice such as FAA-N16 attracts a fine not exceeding S$25,000 and, for a continuing offence, a further fine up to S$2,500 for every day the offence continues after conviction.', trap: 'Breach of a Notice is punishable by fine (S$25,000 plus S$2,500 per day) - there is no imprisonment term for this offence.' },
      { id: 'r3-10', term: 'FAA-N03 general disclosure principles', fact: 'The Notice on Information to Clients and Product Information Disclosure (FAA-N03) requires all information provided to clients to be clear, adequate and not false or misleading, and disclosure documents should be reviewed at least annually. The financial adviser must disclose its name, the services it offers, the products it advises on, any unregulated activities, and its product providers.', trap: 'Disclosure documents must be reviewed at least once a year - not only when a product changes.' },
      { id: 'r3-11', term: 'FAA-N03 product and remuneration disclosures', fact: 'For designated investment products, disclosures include the nature and provider of the product, the client profile it suits, benefits and risks, pricing basis, fees and charges, reports the client will receive, free-look or cancellation period, and warnings. Remuneration must be disclosed; for a life policy, disclosure of the distribution cost in the policy illustration suffices.', trap: 'For life policies the distribution cost shown in the policy illustration satisfies the remuneration disclosure - a separate commission statement is not required.' },
      { id: 'r3-12', term: 'Past and future performance rules', fact: 'FAA-N03 prohibits predictions or forecasts using terms such as \'targeted\' or \'expected\' returns. Past performance must cover a period of at least 1 year ending not earlier than 3 months before use, be computed on an offer-to-bid basis with dividends reinvested, and use average annual compounded returns for periods exceeding 1 year. Simulated or hypothetical performance is not allowed, and an underlying fund\'s track record must be at least 1 year with at least 90 percent invested in it.', trap: 'Even labelling a projection as a \'targeted return\' is prohibited - it is still a forecast.' },
      { id: 'r3-13', term: 'FAA-N11 dual currency investments scope', fact: 'The Notice on Dual Currency Investments (FAA-N11) took effect on 1 March 2006 and applies to financial advisers advising on DCIs, except in respect of accredited investors, expert investors and institutional investors. Key defined terms include base and alternate currency, strike rate, rate-fixing date and spot rate.', trap: 'FAA-N11 does not apply when the client is an accredited, expert or institutional investor.' },
      { id: 'r3-14', term: 'FAA-N11 disclosure and prohibitions', fact: 'A DCI must not be described using the terms \'deposit\' or \'structured deposit\'. The adviser must explain that a DCI embeds a currency option, that the enhanced interest is the option premium, illustrate scenarios where currency movements cause losses, and give the mandatory risk warnings, observing also the Guidelines on Structured Deposits.', trap: 'The enhanced yield on a DCI is the premium for the currency option sold by the client - marketing it as risk-free interest breaches the Notice.' },
    ],
  },
  {
    id: 'r4',
    num: 4,
    title: 'MAS Notices - Part II [Notice Nos: FAA-N02; FAA-N10; FAA-N12; FAA-N14; FAA-N20 And FAA-N26]',
    page: 127,
    concepts: [
      { id: 'r4-01', term: 'FAA-N02 introducers - appointment', fact: 'Under the Notice on Appointment and Use of Introducers (FAA-N02), introducing activity means referring clients to a financial adviser. Introducing must not be the introducer\'s sole business or full-time occupation, and the financial adviser must enter into a written agreement with the introducer and provide a script for use with clients.', trap: 'A person whose sole or full-time occupation is introducing clients cannot be used as an introducer under FAA-N02.' },
      { id: 'r4-02', term: 'Introducer restrictions and register', fact: 'An introducer must not give advice on investment products or handle client\'s money or property, and must disclose to the client that he is an introducer, whether he is remunerated, and the amount of remuneration if the client asks. The financial adviser maintains a register of introducers with their names, contact particulars, registration or identity numbers, and appointment and termination dates. Some requirements are relaxed when introducing is done by the adviser\'s own employees or representatives.', trap: 'An introducer may only make the referral and use the approved script - the moment he discusses product suitability he is giving unauthorised advice.' },
      { id: 'r4-03', term: 'FAA-N10 prohibited representations', fact: 'Persons exempted under Regulation 27(1)(d) - advising not more than 30 accredited investors on investment products other than life policies - and their representatives must not represent that they are licensed, regulated, supervised or registered by MAS.', trap: 'A Regulation 27(1)(d) exempt person cannot even say he is \'registered with MAS\' - all four representations (licensed, regulated, supervised, registered) are prohibited.' },
      { id: 'r4-04', term: 'FAA-N12 provisional representative entry', fact: 'Under the Notice on Entry Requirements of a Provisional Representative (FAA-N12), the individual must be at least 21 years old, be relocating or have relocated to Singapore, have at least 3 years of relevant working experience, and hold a Bachelor\'s degree or equivalent professional qualification. The status is valid for up to 3 months, the overseas licensing must have been continuous for 12 months and ceased not more than 12 months earlier, and a one-time notification is made after passing all required exams.', trap: 'A provisional representative needs 3 years of relevant experience and a degree - passing the CMFAS exams later does not waive the entry criteria.' },
      { id: 'r4-05', term: 'FAA-N14 reportable misconduct', fact: 'The Notice on Reporting of Misconduct (FAA-N14, effect 1 January 2011) requires reporting of four types of misconduct: acts involving fraud or dishonesty (for which a police report must be lodged), inappropriate advice, misrepresentation or inadequate disclosure, failure to satisfy the Guidelines on Fit and Proper Criteria, and other misconduct. Failing continuing education requirements is not reportable misconduct.', trap: 'A representative failing CPD or continuing education requirements is not reportable misconduct under FAA-N14.' },
      { id: 'r4-06', term: 'FAA-N14 reporting timelines', fact: 'A financial adviser must lodge a misconduct report with MAS via MASNET within 14 days of discovery of the misconduct, submit update reports on significant developments including disciplinary action taken, and where there is no misconduct to report, submit a nil annual declaration not later than 14 days after 31 December each year.', trap: 'The misconduct report is due within 14 days of discovery of the misconduct, not within 14 days of concluding the internal investigation.' },
      { id: 'r4-07', term: 'FAA-N20 Independent Sales Audit Unit', fact: 'Under the Balanced Scorecard Framework Notice (FAA-N20), the ISA Unit must be independent of sales; the financial adviser may use its compliance or internal audit or risk management function, or outsource the checks. The ISA Unit\'s findings are reported quarterly to the board and CEO (or an independent unit) by the end of the two calendar quarters after the measurement quarter.', trap: 'The ISA Unit can sit within compliance or be outsourced, but it cannot report to or be part of the sales function.' },
      { id: 'r4-08', term: 'Specified variable income', fact: 'For a representative remunerated only by variable income, 60 percent of the variable income from sales in the measurement quarter is the specified variable income subject to the balanced scorecard. For a representative on fixed plus variable remuneration, all of the variable income is measured. Income is measured only once - deferred payments of measured income are not re-measured.', trap: 'The 60 percent rule applies only to variable-income-only representatives; those with fixed salaries have 100 percent of their variable income measured.' },
      { id: 'r4-09', term: 'Post-transaction checks', fact: 'Post-transaction checks are call-log reviews for representatives who only advise on rollovers of dual currency investments or structured notes, and documentation review plus client surveys for other representatives. Checks on sampled transactions must be completed by the end of the calendar quarter after the measurement quarter, with up to 3 rounds of checks.', trap: 'Client surveys are part of the standard post-transaction checks, but DCI-rollover-only representatives are checked through call-log reviews instead.' },
      { id: 'r4-10', term: 'Sampling requirements', fact: 'Round 1 sampling covers at least 10 percent of transactions of a selected representative (one graded B or worse for two consecutive quarters), 2 percent for a DCI-rollover-only representative, and 5 percent for others, subject to a minimum of one transaction. If infractions are found, round 2 samples an additional 5 percent (DCI) or 10 percent (others), and round 3 an additional 10 percent or 20 percent. Population may be based on historical average or actual transaction count, with actual count required for representatives of less than 3 months or with no transactions in the past 12 months, and a change of method requires 7 days written notice to MAS.', trap: 'A \'selected representative\' is one graded B or worse for two consecutive quarters - a single bad quarter does not trigger the higher 10 percent sampling.' },
      { id: 'r4-11', term: 'Category 1 and Category 2 infractions', fact: 'Category 1 infractions have a material impact on the client\'s interests or impinge on the representative\'s fitness and propriety, such as a clearly unsuitable recommendation, switching detrimental to the client, failure to disclose decisive information, failure to execute instructions causing material loss, misrepresentation, gross negligence or serious misconduct. All other infractions are Category 2, and minor lapses may be disregarded. A case is counted once regardless of the number of infractions in it.', trap: 'One case with several infractions still counts as one case for grading purposes.' },
      { id: 'r4-12', term: 'Representatives\' grading and entitlement', fact: 'Grades are assigned by percentage of cases with infractions or absolute number of Category 2 cases, whichever gives the better grade: A (below 5 percent or 1 case) with 100 percent entitlement; B (5 to below 10 percent or 2 cases) 75 to below 100 percent; C (10 to below 20 percent or 3 cases) 50 to below 75 percent; D (20 to below 30 percent or 4 cases) 25 to below 50 percent; E (30 percent or more, or 5 or more Category 2 cases, or any Category 1 case) 0 to below 25 percent.', trap: 'A single Category 1 case automatically results in grade E regardless of the percentage of cases.' },
      { id: 'r4-13', term: 'Recovery and complaints', fact: 'Specified variable income that the representative is not entitled to must be recovered by the end of the 2 calendar quarters after the measurement quarter, except where the representative is in financial difficulty. Substantiated complaints and mystery shopping results for incidents on or after 1 January 2016 count as cases; for incidents from past quarters, the unentitled amount is prorated by the proportion of the specified variable income earned in the past quarter.', trap: 'Substantiated complaints about past transactions still affect the current quarter\'s grade through proration - they are not ignored because the sale happened earlier.' },
      { id: 'r4-14', term: 'Supervisors under the BSF', fact: 'A supervisor\'s entitlement to specified variable income mirrors the percentage entitlements of the representatives he supervises. Supervisors are graded Good (75 to 100 percent), Satisfactory (50 to below 75 percent), Fair (25 to below 50 percent) and Unsatisfactory (below 25 percent). BSF records must be kept for at least 5 years and each representative and supervisor must receive a balanced scorecard performance record within two quarters after the measurement quarter.', trap: 'Supervisor grades use descriptive bands (Good to Unsatisfactory), not the A to E letter grades used for representatives.' },
      { id: 'r4-15', term: 'FAA-N26 entry and examination requirements', fact: 'The Notice on Competency Requirements (FAA-N26) took effect on 1 April 2024, cancelling FAA-N13. An appointed representative must be at least 21 years old and hold a GCE A Level certificate (three H2 and two H1 passes), an International Baccalaureate Diploma, a polytechnic diploma or an equivalent qualification. The examination requirement is a valid pass in RES5 plus the relevant product knowledge modules (for example M9 and M9A for life policies, with combined modules such as CM-LIP available). Exemptions apply for holders of qualifications such as a finance degree or CFA for certain modules.', trap: 'FAA-N26 took effect on 1 April 2024 and replaced the earlier competency notice FAA-N13.' },
      { id: 'r4-16', term: 'FAA-N26 validity and CPD requirements', fact: 'A pass in RES5 lapses if the individual does not commence as an appointed representative within 3 years of passing, or ceases and does not recommence within 3 years. Each calendar year an appointed representative must complete 6 Core CPD hours (an IBF or SCI accredited course in ethics or rules and regulations, or a CPF Board course) plus Supplementary CPD hours of 24 hours (10 hours if advising only on mortgage reducing term assurance or group term life policies), pro-rated by days appointed over 365 for partial years. The first calendar year of first appointment is exempt, and the principal must maintain a register of each representative\'s qualifications and CPD evidence for at least 5 years.', trap: 'Core CPD is 6 hours in ethics or rules and regulations - general product training does not count towards the core requirement.' },
    ],
  },
  {
    id: 'r5',
    num: 5,
    title: 'MAS Notice No: FAA-N06 - Prevention Of Money Laundering And Countering The Financing Of Terrorism - Financial Advisers',
    page: 251,
    concepts: [
      { id: 'r5-01', term: 'FAA-N06 scope', fact: 'Notice FAA-N06 is issued under Section 27B of the MAS Act and applies to licensed financial advisers, registered insurance brokers exempt from FA licensing, and persons exempt under Regulation 27(1)(d) of the FAR, except those which only provide advice by issuing or promulgating research analyses or research reports.', trap: 'Advisers that only issue research analyses or reports are outside the scope of FAA-N06.' },
      { id: 'r5-02', term: 'Underlying AML/CFT principles', fact: 'FAA-N06 rests on three principles: exercise due diligence when dealing with customers, persons appointed to act on their behalf, connected parties and beneficial owners; conduct business in conformity with high ethical standards and guard against transactions connected with money laundering or terrorism financing; and assist and cooperate with Singapore law enforcement to the fullest extent possible.', trap: 'Cooperation with law enforcement is a stated principle - customer confidentiality does not override AML/CFT obligations.' },
      { id: 'r5-03', term: 'Risk-based approach', fact: 'A financial adviser must identify, assess and understand its money laundering and terrorism financing risks across its customers, the countries its customers are from or in, the countries it operates in, and its products, services, transactions and delivery channels. Risk assessments must be documented, kept up to date and available to MAS, and mitigation policies must be approved by senior management with enhanced measures for higher risks.', trap: 'Risk assessments must be documented and kept current - an informal, undocumented assessment does not satisfy the Notice.' },
      { id: 'r5-04', term: 'New products and technologies', fact: 'The financial adviser must assess money laundering and terrorism financing risks arising from new products, business practices and delivery mechanisms, and from new or developing technologies, before their launch or use, paying special attention to anything that favours anonymity.', trap: 'The risk assessment must be done before launching the new product or technology, not after.' },
      { id: 'r5-05', term: 'When CDD is required', fact: 'No anonymous or fictitious accounts may be opened or maintained. CDD must be performed when establishing business relations, when there is suspicion of money laundering or terrorism financing, or when there are doubts about the veracity or adequacy of information previously obtained. Where suspicion exists before establishing relations, the adviser must not establish relations or undertake the transaction, and must file an STR with a copy to MAS.', trap: 'Suspicion triggers CDD even where the Notice would not otherwise require it - and pre-relationship suspicion means declining the business and filing an STR.' },
      { id: 'r5-06', term: 'Customer identification and verification', fact: 'The adviser must obtain at least the customer\'s full name including aliases, unique identification number, residential or registered address, date of birth or incorporation, and nationality or place of incorporation, and verify identity using reliable, independent source data. For legal persons it must identify connected parties and understand ownership and control. Natural persons acting for a customer must be identified, verified and their authority evidenced. Joint account holders are each treated as customers.', trap: 'For a joint account, CDD is performed on all holders as if each were individually a customer - not just the primary holder.' },
      { id: 'r5-07', term: 'Beneficial owners', fact: 'A beneficial owner is the natural person who ultimately owns or controls the customer or on whose behalf the transaction is conducted. Identification follows a cascade for legal persons: ultimate owners, then those with ultimate effective control, then persons with executive authority. For trusts, the settlor, trustees, protector, beneficiaries and controllers must be identified. Inquiry is not required for entities listed on the SGX, certain listed foreign entities, financial institutions in Appendix 5A, FATF-compliant foreign financial institutions, and investment vehicles they manage, unless there are doubts or suspicion.', trap: 'The beneficial owner exemption for listed entities and regulated financial institutions falls away where the adviser doubts the CDD information or suspects money laundering.' },
      { id: 'r5-08', term: 'Timing of verification and incomplete CDD', fact: 'Verification of customers, persons acting on their behalf and beneficial owners must be completed before establishing business relations, though it may be deferred if essential to avoid interrupting normal business and the risks can be effectively managed, with completion as soon as reasonably practicable. Where CDD measures cannot be completed, the adviser must not commence or continue business relations or undertake transactions and must consider filing an STR. Customers and related parties must also be screened against relevant lists at onboarding, periodically, and upon changes.', trap: 'If CDD cannot be completed, the relationship must be declined or terminated - proceeding with heightened monitoring is not an option.' },
      { id: 'r5-09', term: 'Simplified CDD', fact: 'Simplified CDD may be performed where the adviser is satisfied that money laundering and terrorism financing risks are low, supported by an adequate and documented analysis. It is prohibited where the customer or beneficial owner is from a country subject to FATF countermeasures or known to have inadequate AML/CFT measures, or where money laundering or terrorism financing is suspected.', trap: 'Simplified CDD requires a documented low-risk analysis and is never allowed where FATF countermeasures apply or suspicion exists.' },
      { id: 'r5-10', term: 'Enhanced CDD and politically exposed persons', fact: 'A politically exposed person is a person entrusted with prominent public functions, domestically, in a foreign country, or in an international organisation; family members and close associates are covered. For foreign PEPs, the adviser must obtain senior management approval for the relationship, establish source of wealth and source of funds, and conduct enhanced ongoing monitoring. A risk-based approach may be taken for domestic PEPs, international organisation PEPs and PEPs who have stepped down, unless the relationship is higher risk.', trap: 'Enhanced CDD is mandatory for foreign PEPs, while domestic and international organisation PEPs may be handled on a risk-based approach.' },
      { id: 'r5-11', term: 'Reliance on third parties and record keeping', fact: 'An adviser may rely on specified third parties for CDD if the third party is supervised for FATF-consistent AML/CFT compliance, country risks are assessed, the third party is not precluded by MAS, and it will provide CDD data without delay - but ongoing monitoring cannot be delegated and the adviser remains responsible. CDD records must be kept for at least 5 years after termination of business relations, and transaction records for at least 5 years after completion of the transaction.', trap: 'Ongoing monitoring of business relations can never be outsourced to a third party, and reliance does not transfer responsibility.' },
      { id: 'r5-12', term: 'STRs, compliance, audit and training', fact: 'Suspicious transactions, including attempted ones, must be reported promptly to the Suspicious Transaction Reporting Office (STRO) regardless of amount, with a copy to MAS. A single reference point must receive internal referrals, and Section 48 of the CDSA prohibits tipping-off; where performing CDD would tip off the customer, the adviser may stop and file an STR. The adviser must appoint an AML/CFT compliance officer at management level, maintain an independent audit function, screen prospective employees and representatives, and train staff regularly. Personal data may be collected, used and disclosed for compliance without the individual\'s consent.', trap: 'STRs must be filed regardless of transaction size - there is no minimum amount threshold.' },
    ],
  },
  {
    id: 'r6',
    num: 6,
    title: 'MAS Notices - Part III [Notices Nos: FAA-N17; FSM-N23; FAA-N19 And FSM-N24]',
    page: 278,
    concepts: [
      { id: 'r6-01', term: 'FAA-N17 scope', fact: 'Notice FAA-N17 on Reporting of Suspicious Activities and Incidents of Fraud is issued under section 58 of the FAA 2001 and requires licensed FAs to report to MAS suspicious activities and incidents of fraud that are material to the safety, soundness or reputation of the FA.', trap: 'FAA-N17 reporting to MAS is in addition to, not instead of, filing suspicious transaction reports with STRO.' },
      { id: 'r6-02', term: 'Form F1 timeline', fact: 'Under FAA-N17, the FA must submit a report to MAS in Form F1 not later than 5 working days after discovering a suspicious activity or incident of fraud that is material to its safety, soundness or reputation.', trap: 'The clock runs from discovery of the incident, not from completion of the internal investigation.' },
      { id: 'r6-03', term: 'Fraud - police report', fact: 'Where an incident of fraud is discovered, FAA-N17 expects the FA to lodge a police report and submit a copy of that police report to MAS, in addition to any suspicious transaction reports filed with STRO, CAD or the Police.', trap: 'A police report does not replace the Form F1 report to MAS; both are required where the materiality test is met.' },
      { id: 'r6-04', term: 'Decision not to report', fact: 'If the FA assesses that a suspicious activity or fraud incident is not material to its safety, soundness or reputation and decides not to report it to MAS, it should document the reasons for not reporting.', trap: 'Non-materiality does not remove the need to keep a documented record of the assessment.' },
      { id: 'r6-05', term: 'FSM-N23 downtime limit', fact: 'Notice FSM-N23 on Technology Risk Management, issued under section 29(1) of the FSM Act 2022 and effective 10 May 2024, requires that the maximum unscheduled downtime for each critical system must not exceed a total of 4 hours within any period of 12 months.', trap: 'The 4-hour cap is a cumulative total per 12 months per critical system, not 4 hours per incident.' },
      { id: 'r6-06', term: 'FSM-N23 recovery time objective', fact: 'Under FSM-N23, the recovery time objective (RTO) of each critical system must not exceed 4 hours, and the FA must validate and document that the RTO can be met at least once every 12 months.', trap: 'RTO validation is an annual exercise; setting the RTO once is not sufficient.' },
      { id: 'r6-07', term: 'FSM-N23 incident notification', fact: 'FSM-N23 requires the FA to notify MAS as soon as possible, but not later than 1 hour, upon discovery of a relevant system malfunction or IT security incident, and to submit a root cause and impact analysis report within 14 days of the incident discovery.', trap: 'The 1-hour notification runs from discovery of the incident, and the 14-day report is a separate follow-up obligation.' },
      { id: 'r6-08', term: 'FAA-N19 distribution channels', fact: 'Notice FAA-N19 requires direct purchase insurance products (DPI) to be distributed only through a representative or customer service officer, or through an online direct channel, and a Tier 1 life insurer must at a minimum offer DPI through a representative or customer service officer at its principal place of business or a branch.', trap: 'A mobile branch does not count as a branch for the Tier 1 insurer minimum distribution requirement.' },
      { id: 'r6-09', term: 'FAA-N19 alerts and documents', fact: 'Under FAA-N19, clients purchasing DPI must be alerted that DPI is not a savings account or deposit, that they may not get back premiums paid if the policy is terminated early, that some benefits are not guaranteed, and that a 14-day free-look period applies; the FA must furnish the documents in paragraph 37(b) of FAA-N16 plus the LIA fact sheet and checklist, and review the documents at least annually.', trap: 'A customer service officer must not provide any financial advisory service that is not solely incidental to the distribution of DPI.' },
      { id: 'r6-10', term: 'Section 58(5) penalty', fact: 'Failure to comply with a MAS notice such as FAA-N19 is an offence under section 58(5) of the FAA, punishable with a fine not exceeding $25,000 and, in the case of a continuing offence, a further fine not exceeding $2,500 for every day the offence continues after conviction; the FAA-N19 Amendment 2019 took effect on 30 August 2019.', trap: 'The daily fine of $2,500 applies to the continuing offence after conviction, on top of the initial fine.' },
      { id: 'r6-11', term: 'FSM-N24 cyber hygiene', fact: 'Notice FSM-N24 on Cyber Hygiene, issued under section 29(1) of the FSM Act 2022 and effective 10 May 2024, mandates six practices: securing administrative accounts, applying security patches, having written security standards, network perimeter defence, malware protection, and multi-factor authentication for all administrative accounts of critical systems and all accounts used to access customer information through the internet.', trap: 'MFA is required both for administrative accounts of critical systems and for any account accessing customer information over the internet, not only for admin accounts.' },
    ],
  },
  {
    id: 'r7',
    num: 7,
    title: 'Notice No: MAS 307 - Investment-linked Policies (ILPs)',
    page: 301,
    concepts: [
      { id: 'r7-01', term: 'MAS 307 structure', fact: 'MAS Notice 307 on Investment-Linked Policies is issued under section 64(2) of the Insurance Act; Part I is mandatory while Part II sets out non-mandatory best practice standards; the Notice took effect on 1 October 2011 and was last revised on 28 June 2021.', trap: 'Only Part I is mandatory; Part II standards are best practices, not requirements.' },
      { id: 'r7-02', term: 'Sub-fund notifications to MAS', fact: 'An insurer must notify MAS at least 21 days before launching a new ILP sub-fund, and must notify policyholders of significant changes no later than 1 month before the change takes effect, including any fee increase of 0.1% or more of NAV and changes to an underlying fund into which the sub-fund feeds 30% or more of its NAV.', trap: 'The 21-day notice is to MAS for new sub-fund launches; the 1-month notice is to policyholders for significant changes.' },
      { id: 'r7-03', term: 'Unit pricing', fact: 'Units in an ILP sub-fund must be priced at the sub-fund\'s NAV divided by the number of units outstanding, and units of a capital guaranteed sub-fund must be redeemed at maturity at the higher of the guaranteed amount and the NAV per unit.', trap: 'The capital guaranteed redemption is the higher of the two amounts, never simply the guaranteed amount.' },
      { id: 'r7-04', term: 'Audit methods', fact: 'An insurer may have its ILP sub-funds audited under the first method (audit of financial statements) or the second method (audit of internal controls); it must notify MAS before first changing to the second method, the inaugural second-method audit must be completed within 3 months of the financial year end, and the review period must not be less than 12 months.', trap: 'MAS notification is required before the first change to the second method, not after.' },
      { id: 'r7-05', term: 'Terminated sub-fund audits', fact: 'For a terminated or matured ILP sub-fund, the audit certificate must be obtained within 6 months of termination or maturity, a copy sent to MAS within 30 days of the audit\'s completion, records retained for 5 years, and a copy provided to a policyholder within 30 days of request.', trap: 'The 30-day MAS submission runs from completion of the audit, not from the termination date.' },
      { id: 'r7-06', term: 'Premium charge terminology', fact: 'For ILPs issued on or after 8 October 2021, insurers must use a single "premium charge" and must not use the term "premium allocation rate".', trap: 'The ban on "premium allocation rate" applies to policies issued on or after 8 October 2021, not retrospectively to all in-force ILPs.' },
      { id: 'r7-07', term: 'Statement frequency', fact: 'Statements for specified ILPs, meaning regular premium ILPs and single or recurrent single premium ILPs whose death and critical illness benefits are at least 150% of premiums, must be sent annually within 30 days of the policy anniversary; statements for all other ILPs must be sent monthly.', trap: 'It is the specified ILPs that get annual statements; other ILPs require monthly statements, not the reverse.' },
      { id: 'r7-08', term: 'Sub-fund reports', fact: 'Insurers must send policyholders the Semi-Annual Report within 2 months and the Relevant Audit Report within 3 months of the relevant period end; the underlying fund\'s reports may be substituted only where the minimum subscription is a single premium of at least USD50,000 or annualised regular premiums of at least USD5,000, the policy is not CPF-included, and the policyholder gives written consent.', trap: 'All three substitution conditions must be met, including written policyholder consent.' },
      { id: 'r7-09', term: 'Hardcopy election', fact: 'Where reports are provided electronically, policyholders must be given at least one month to opt for hardcopies, a hardcopy must be provided within two weeks of a request, and reports posted on a website must remain available for at least 12 months.', trap: 'The 12-month posting period applies to website availability, distinct from the two-week hardcopy fulfilment deadline.' },
      { id: 'r7-10', term: 'Expense prohibitions', fact: 'MAS 307 prohibits charging marketing and promotion expenses to an ILP sub-fund, retaining cash rebates from brokers, receiving soft dollars except under strict conditions, receiving travel, accommodation or entertainment benefits, and charging costs of failed CPF trades to the sub-fund.', trap: 'Soft dollars are not banned outright; they are permitted only under conditions such as assisting in the provision of advice and best execution.' },
      { id: 'r7-11', term: 'EIP-ILP treatment', fact: 'Where an ILP sub-fund invests in an underlying CIS that ceases to be an Excluded Investment Product, the insurer must either dispose of the underlying EIP-CIS within 3 months (extendable to 12 months with monthly re-satisfaction) or reclassify the ILP as a Specified Investment Product within 4 months and apply the Customer Knowledge Assessment.', trap: 'The disposal route allows 3 months (extendable), while the reclassification route allows 4 months; the two timelines are different.' },
      { id: 'r7-12', term: 'Redemption and dealing standards', fact: 'Under the non-mandatory standards, redemption proceeds should be paid within T+4 business days for bond and money market sub-funds, T+7 for sub-funds feeding into a CIS, and T+6 for others; sub-funds should deal at least once a month, and any dealing suspension should cease within 21 days subject to weekly review.', trap: 'T+7 applies to feeder sub-funds; the general standard for other sub-funds is T+6, not T+7.' },
      { id: 'r7-13', term: 'Valuation and rounding', fact: 'ILP sub-fund units should be valued every business day (or at least monthly where dealing is not daily, with property valued yearly), and rounding differences from pricing should be credited to the sub-fund; for example, if the true price is $1.224 and 10,000 units are redeemed at $1.22, $40 is credited to the sub-fund.', trap: 'Rounding differences go to the sub-fund, not to the insurer or the policyholder.' },
      { id: 'r7-14', term: 'Valuation errors', fact: 'Where a valuation error is 0.5% or more of the NAV per unit, the insurer should compensate affected policyholders (unless the amount per policyholder does not exceed $20) and must always compensate the sub-fund.', trap: 'The $20 de minimis relieves compensation to an individual policyholder only; the sub-fund itself must always be compensated.' },
      { id: 'r7-15', term: 'Advertising and PHS standards', fact: 'ILP advertisements citing past performance should use periods of at least 1 year ending no more than 3 months before the advertisement, must not use simulated results, should use font no smaller than 10-point Times New Roman, with a 5-second display for broadcast statements; the Product Highlights Sheet should not exceed four pages, or eight pages including diagrams and a glossary, and must not contain disclaimers.', trap: 'The PHS page limit stretches to eight pages only where diagrams and a glossary are included.' },
    ],
  },
  {
    id: 'r8',
    num: 8,
    title: 'MAS Guidelines - Part I [Guideline Nos: FAA-G01; FSG-G01; FAA-G04 & FAA-G05] And Circular No: CMI 01/2011',
    page: 358,
    concepts: [
      { id: 'r8-01', term: 'FA licence - form and staffing', fact: 'Under FAA-G01, a financial adviser\'s licence is granted only to a corporation with a physical presence in Singapore, and the applicant must have a minimum of 2 full-time appointed representatives.', trap: 'Individuals and partnerships cannot hold an FA licence; only corporations qualify.' },
      { id: 'r8-02', term: 'Management and board criteria', fact: 'The CEO and executive directors of an FA licence applicant should each have at least 5 years of relevant working experience including 3 years in a managerial capacity; the board must have at least 2 directors, one of whom is resident in Singapore, and the CEO must be resident in Singapore.', trap: 'The 3 years of managerial experience is part of, not in addition to, the 5 years of relevant experience.' },
      { id: 'r8-03', term: 'Minimum paid-up capital', fact: 'An FA licence applicant must have minimum paid-up capital of $150,000 if advising on or arranging life policies, or $300,000 if its activities include advising on futures contracts, spot foreign exchange for leveraged trading, or over-the-counter currency derivatives.', trap: 'The higher $300,000 tier is triggered by futures and leveraged FX activities, not by life policies.' },
      { id: 'r8-04', term: 'Professional indemnity insurance', fact: 'An FA licensee must maintain professional indemnity insurance of at least $500,000, with any deductible not exceeding 20% of the licensee\'s net asset value; where cover is under a group policy, the group PII quantum should be 5 times the required amount.', trap: 'The 20% cap applies to the deductible relative to net asset value, not to the sum insured.' },
      { id: 'r8-05', term: 'Track record and shareholding', fact: 'An FA licence applicant should have a 3-year corporate track record; where it lacks one, MAS may still consider the application if the CEO holds at least 20% of the shares and the CEO and executive directors together hold at least 50%.', trap: 'The shareholding route is an alternative for applicants without the 3-year track record, not an additional requirement for all applicants.' },
      { id: 'r8-06', term: 'Representative entry requirements', fact: 'Minimum entry requirements for an appointed representative include being at least 21 years old, passing the relevant CMFAS examinations required under Notice FAA-N13, and satisfying MAS\'s fit and proper criteria.', trap: 'Passing the CMFAS exams alone is not sufficient; the age and fit and proper criteria must also be met.' },
      { id: 'r8-07', term: 'FSG-G01 fit and proper criteria', fact: 'Guidelines FSG-G01 set out three fit and proper criteria: honesty, integrity and reputation; competence and capability; and financial soundness, with the onus on the relevant person to demonstrate fitness and propriety.', trap: 'Failure to meet one criterion does not automatically lead to refusal; MAS considers the circumstances in the round.' },
      { id: 'r8-08', term: 'CMI 01/2011 due diligence', fact: 'Circular CMI 01/2011 expects FAs conducting due diligence on prospective representatives to obtain written self-declarations covering a 10-year lookback, perform reference checks with previous employers, check the MAS Public Register and conduct probity searches, including bankruptcy checks with IPTO and CPF contribution arrears checks for the self-employed.', trap: 'The self-declaration lookback period is 10 years, not 5.' },
      { id: 'r8-09', term: 'Declarations and notifications', fact: 'Under CMI 01/2011, it is an offence to employ a person subject to a prohibition order; a person who makes a false statement in a declaration lodged with MAS through the principal is liable to a fine of up to $50,000; declarations should be renewed annually and MAS notified of changes in a representative\'s particulars within 14 days.', trap: 'The $50,000 fine attaches to false statements in declarations lodged with MAS; the notification window for changes in particulars is 14 days.' },
      { id: 'r8-10', term: 'FAA-G04 standards of conduct', fact: 'Guidelines FAA-G04 set standards of professional conduct including integrity, objectivity, confidentiality, competence, due care, disclosure (including the \'distribution cost\' in the Benefit Illustration for life policies), knowing your client, having a reasonable basis for recommendations, record keeping, managing conflicts of interest, complaints handling with a designated officer and register, and compliance.', trap: 'Offering to rebate commission is not an acceptable substitute for a reasonable basis for a recommendation.' },
      { id: 'r8-11', term: 'Use of \'independent\'', fact: 'Under FAA-G05 and Regulation 21 of the FAR, an FA may call itself \'independent\' only if it operates free from commission bias, is not restricted in the range of products it advises on, and has no conflicts of interest arising from links with product providers; product providers should not use the term, and a breach is an offence.', trap: 'All three independence conditions must be satisfied; meeting only one or two does not permit use of the term.' },
      { id: 'r8-12', term: 'Independence thresholds', fact: 'FAA-G05 treats commissions from a single product provider exceeding 20% of an FA\'s total annual revenue, and differences of more than 20% in commission rates between product providers, as significant for assessing commission bias; an FA advising on products from fewer than four product providers in a class would generally not be considered independent for that class.', trap: 'Fewer than four product providers per product class defeats independence for that class even if no commission bias exists.' },
    ],
  },
  {
    id: 'r9',
    num: 9,
    title: 'MAS Guidelines - Part II [Guideline Nos: FAA-G09; FAA-G10; FSG-G04 And FAA-G14]',
    page: 404,
    concepts: [
      { id: 'r9-01', term: 'FAA-G09 scope', fact: 'Guidelines FAA-G09 on structured deposits do not apply where the structured deposit is sold to accredited investors, expert investors or institutional investors.', trap: 'The carve-out covers accredited, expert and institutional investors; retail clients remain fully protected by the Guidelines.' },
      { id: 'r9-02', term: 'Structured deposit disclosures', fact: 'Under FAA-G09, a product must not be labelled a deposit unless it falls within the definition (dual currency investments fall under Notice FAA-N11); clients must be told that early withdrawal may mean loss of part of the principal and that structured deposits are not insured under the Deposit Insurance Act, with warnings given where no advice is provided.', trap: 'Unlike conventional deposits, structured deposits are not covered by deposit insurance.' },
      { id: 'r9-03', term: 'SD competency and premises', fact: 'Representatives marketing structured deposits should pass CMFAS Module 5 and Module 8 or receive equivalent firm training; bank tellers should not market structured deposits, elderly customers should be screened, and a booth that accepts applications constitutes a new place of business requiring MAS approval under section 12 of the Banking Act.', trap: 'A booth merely distributing brochures differs from one accepting applications; only the latter is a new place of business needing approval.' },
      { id: 'r9-04', term: 'FAA-G10 switching safeguards', fact: 'Guidelines FAA-G10 require an FA recommending a switch to disclose in writing all fees, charges and disadvantages together with a prescribed warning, obtain the client\'s written declaration on whether he was advised to switch, have the representative declare any free switching entitlement, and have a supervisor review the transaction in line with paragraph 42 of FAA-N16.', trap: 'The client, the representative and the supervisor each have a distinct declaration or review role; one signature does not cover all three.' },
      { id: 'r9-05', term: 'Switching monitoring', fact: 'FAs should conduct back-end monitoring of switching trends to detect undesirable practices and should not remunerate representatives solely on the basis of sales volume.', trap: 'Monitoring is expected at the firm level after the sale, in addition to front-end supervisor reviews.' },
      { id: 'r9-06', term: 'Fair dealing five outcomes', fact: 'Guidelines FSG-G04 set five fair dealing outcomes: fair dealing is central to corporate culture; products are suitable for their target segments; representatives are competent; customers receive clear, relevant and timely information; and complaints are handled independently, effectively and promptly.', trap: 'Outcome one concerns corporate culture driven by the board and senior management, not merely front-line conduct.' },
      { id: 'r9-07', term: 'Fair dealing implementation', fact: 'Under FSG-G04, senior executives\' remuneration should be linked to fair dealing KPIs, product due diligence should be independent, all Specified Investment Products are treated as complex products, a good practice remuneration mix is 40% sales and 60% non-sales measures, fee changes require at least 30 days\' notice, unresolved complaints may go to FIDReC, and complaints records are kept for 5 years.', trap: 'The 40/60 sales to non-sales remuneration split is cited as good practice, not a mandated ratio.' },
      { id: 'r9-08', term: 'Selected client definition', fact: 'Under FAA-G14, a \'selected client\' is one who meets any two of: aged 62 years or older; not proficient in spoken or written English; and educational qualification below GCE O-level or N-level, unless a documented assessment shows adequate investment experience.', trap: 'Any two of the three criteria must be met; one alone does not make a client a selected client.' },
      { id: 'r9-09', term: 'Effective date of transaction', fact: 'FAA-G14 defines the effective date for a life policy as the latest of the date the policy is issued, takes effect or cover commences, and for other investment products as the date the application is accepted by the product manufacturer.', trap: 'For life policies it is the latest of the three dates, not the application date.' },
      { id: 'r9-10', term: 'Post-transaction checks', fact: 'The ISA Unit must perform post-transaction checks every calendar quarter, comprising both a documentation review and a client survey on each sampled transaction; a phone survey may be closed after three unsuccessful call attempts, a written survey after one month, and an electronic survey after two weeks, and the representative is not penalised for a client\'s non-participation.', trap: 'Both the documentation review and the client survey must be done on each sampled transaction; one does not substitute for the other.' },
      { id: 'r9-11', term: 'Infraction categories', fact: 'Infractions under the balanced scorecard framework are classified as Category 1 or Category 2; Annex 3 Category 1 examples across KPIs 1 to 4 include insufficient fact-finding, unsuitable recommendations, non-disclosure of key features and risks, misleading statements, falsifying client responses, pre-signed blank forms, harassment and allowing unauthorised persons to advise.', trap: 'Category 1 infractions have a material impact on clients\' interests; administrative lapses generally fall under Category 2.' },
      { id: 'r9-12', term: 'Grade E representative measures', fact: 'A representative assigned grade E in a quarter must be placed under close supervision with oversight by the CEO or a designate other than his supervisor, be accompanied by the supervisor for a minimum of five closed sales, have the ISA Unit conduct full-scale checks on every transaction for a minimum of three months, and must not hold any supervisory or managerial role for at least one year from the grade assignment.', trap: 'A closed sale requires fact-find, needs analysis, recommendation and client acceptance; accompanying five prospecting meetings does not count.' },
      { id: 'r9-13', term: 'Unsatisfactory supervisor', fact: 'Where a supervisor is graded Unsatisfactory, the FA should review the adequacy of his oversight and may reduce the number of representatives under him or impose a recruitment moratorium; if his own direct supervisor is also Unsatisfactory in the same quarter, a higher-tier supervisor performs the role, and a supervisor graded Unsatisfactory for two consecutive quarters must not hold a supervisory or managerial role for at least one year from the second consecutive grade.', trap: 'The one-year bar for supervisors requires two consecutive Unsatisfactory quarters, whereas a representative\'s bar is triggered by a single grade E.' },
      { id: 'r9-14', term: 'BSC reference checks', fact: 'When conducting reference checks on a prospective representative or supervisor, an FA should request the individual\'s last four balanced scorecard grades within the past 10 years, and the responding FA should disclose those grades, including both sets where the individual served as both representative and supervisor.', trap: 'The request covers the last four grades within 10 years, not simply the last year\'s grades.' },
      { id: 'r9-15', term: 'Pre-transaction checks', fact: 'Under FAA-G14, effective 1 January 2016, supervisors must review all documentation and the basis of every recommendation before submission to product manufacturers (except rollovers of dual currency investments or structured notes relating to equities or commodities); infractions found pre-transaction are not factored into the balanced scorecard; call-backs are made to selected clients, and for selected representatives to every client no later than the end of the next quarter; checks not completed before the effective date must be completed within the free-look or cancellation period, or within 5 business days for time-sensitive products without one, and records are kept for at least five years.', trap: 'Pre-transaction infractions do not count against the balanced scorecard grade or remuneration; only post-transaction findings do.' },
    ],
  },
  {
    id: 'r10',
    num: 10,
    title: 'MAS Guidelines - Part III [Guideline Nos: FAA-G13; FAA-G15; FAA-G16; CMG-G02 And FSG-G02]',
    page: 484,
    concepts: [
      { id: 'r10-01', term: 'FAA-G13 scope', fact: 'Guidelines FAA-G13, issued under section 64 of the FAA, address conflicts of interest for FAs issuing research analyses or research reports on clearly identifiable investment products; general economic or asset-allocation research is excluded, and internal policies must be approved by senior management.', trap: 'Research on broad economic trends or asset allocation is outside FAA-G13; only research on identifiable investment products is covered.' },
      { id: 'r10-02', term: 'Analyst separation', fact: 'Under FAA-G13, research analysts should be functionally separated from sales, trading, dealing and corporate finance; research reports should not be reviewed or approved by those functions; analyst compensation should not be based on specific transactions of those functions, and favourable coverage must not be offered as consideration for business.', trap: 'The prohibition is on linking analyst pay to specific transactions, and on trading favourable coverage for business, not on analysts being paid from firm profits generally.' },
      { id: 'r10-03', term: 'Research disclosures and records', fact: 'FAA-G13 requires conflicts to be disclosed in writing in a clear and prominent manner; boilerplate statements that the FA \'may or may not\' have an interest are insufficient, and records of the bases of recommendations must be kept for not less than 5 years from publication.', trap: 'Generic \'may or may not have an interest\' disclaimers do not satisfy the disclosure standard.' },
      { id: 'r10-04', term: 'FAA-G15 scope', fact: 'Guidelines FAA-G15 on online distribution of life policies with no advice took effect on 31 March 2017; before offering an insurer\'s life policy online without advice, the FA should also make available that insurer\'s equivalent direct purchase insurance product on its online direct channel.', trap: 'The equivalent DPI must be offered on the same online channel; offering only the full-priced policy online is not sufficient.' },
      { id: 'r10-05', term: 'Online sale safeguards', fact: 'Under FAA-G15, the client should receive the documents under paragraph 37(b) of FAA-N16 plus the full policy wordings, acknowledge the items in Annex A, and be shown prominent statements or pop-ups that the policy is not a savings account or deposit, that premiums may not be recovered on early termination, that some benefits are not guaranteed, that a 14-day free-look applies, that he can request an explanation, and that he should consider suitability since no advice is given; conditional acceptance such as exclusions or premium loadings must be highlighted.', trap: 'Even with no advice given, risk warnings, free-look disclosure and conditional acceptance highlights are still required.' },
      { id: 'r10-06', term: 'FAA-G15 tools and exemption', fact: 'FAA-G15 Annex B expects online channels to direct clients to tools such as the CPF Insurance Estimator, the MoneySense Budget Calculator and comparefirst.sg, and the Guidelines are not expected to apply to monthly renewable group term policies since these carry no long-term commitment.', trap: 'The group term carve-out rests on the absence of long-term commitment; ordinary individual term policies remain within scope.' },
      { id: 'r10-07', term: 'FAA-G16 ACMF framework', fact: 'Guidelines FAA-G16 implement the ASEAN Capital Market Professional Mobility Framework, whose MOU was signed on 11 October 2018 and took effect on 1 January 2019; a relevant foreign entity operates as an exempt FA under section 23(1)(f) of the FAA through an approved arrangement under Regulation 32CB with a host Singapore Entity or Hosting Platform Operator.', trap: 'The foreign entity relies on an approved arrangement and exemption, not on holding its own Singapore FA licence.' },
      { id: 'r10-08', term: 'ACMF arrangements and criteria', fact: 'FAA-G16 recognises two arrangement types: the ACMF Pass, for advising on Specified ASEAN capital markets products (listed shares, bonds including sukuk, and CIS units), and the Cross-Border Publication of Research Report Arrangement; the foreign entity must have a minimum five-year corporate track record, be financially sound, and be licensed and supervised by a Recognised ACMF member, with participating regulators being Thailand\'s SEC, SC Malaysia and the Philippines\' SEC.', trap: 'Specified ASEAN capital markets products cover listed shares, bonds and CIS units, not derivatives or life policies.' },
      { id: 'r10-09', term: 'Digital advisory licensing', fact: 'Guidelines CMG-G02 on digital advisory services are issued under section 321 of the SFA and section 64 of the FAA; there is no separate authorisation regime for digital advisers because licensing is technology-agnostic, so digital advisers are licensed under the existing SFA or FAA regimes.', trap: 'Being a robo-adviser does not require a special licence category; the ordinary FA or fund management licensing rules apply.' },
      { id: 'r10-10', term: 'Digital adviser exemptions', fact: 'Under CMG-G02, FA digital advisers may rely on the Dealing Exemption to pass client orders to brokers for specified products other than OTC derivatives, regardless of whether the client accepted the recommendation, and on the Fund Management Exemption to rebalance portfolios consisting solely of CIS, subject to one-time prior written client authorisation, written disclosure of scope, fees and notice period, and notification before every rebalancing.', trap: 'The rebalancing exemption requires notification before every rebalancing, not just the one-time authorisation.' },
      { id: 'r10-11', term: 'Digital adviser restrictions', fact: 'FA digital advisers must not handle client moneys or assets or operate omnibus accounts; retail fund management applicants lacking a 5-year track record or S$1 billion AUM may still be considered if key individuals have fund management and technology experience, portfolios comprise only CIS that are in-substance Excluded Investment Products, an independent post-authorisation audit is done at the end of the first year, the adviser does not manufacture the underlying CIS, and the tools are fully automated.', trap: 'The relaxed admission route is for fund management applicants; FA digital advisers still cannot hold client assets at all.' },
      { id: 'r10-12', term: 'Algorithm governance', fact: 'Under CMG-G02, the Board and Senior Management are responsible for governance and supervision of the algorithms and remain ultimately responsible even where development is delegated; controls should include knock-out questions to eliminate unsuitable clients, means to suspend advice when an error or bias is detected, and compliance checks on the algorithm reviewed by an independent qualified human adviser.', trap: 'Outsourcing algorithm development does not transfer responsibility away from the Board and Senior Management.' },
      { id: 'r10-13', term: 'FAA-N16 exception for robo-advice', fact: 'A fully-automated digital adviser need not collect the full client information under paragraph 11(c) to (i) of FAA-N16 if the tool is fully automated with no human intervention, uses knock-out questions, has controls to detect inconsistent responses, provides a risk disclosure statement, and limits advice to CIS that are in-substance Excluded Investment Products; it must still collect the client\'s financial objectives and risk tolerance, CKA and CAR requirements still apply, and the balanced scorecard framework does not apply where no representatives advise clients directly.', trap: 'The exception never removes the need to collect financial objectives and risk tolerance, and CKA/CAR still apply.' },
      { id: 'r10-14', term: 'FSG-G02 retail marketing safeguards', fact: 'Guidelines FSG-G02 on marketing and distribution at retailers and public places took effect on 1 April 2017 and set out twelve safeguards, including call-backs or surveys for all customers prospected at such locations before or within the free-look or cooling-off period (covering life insurance, accident and health policies and CIS, with simple life policies ancillary to loans exempt but not mortgage reducing term assurance), mystery shopping and site visits covering at least half of all arrangements each year, a register of arrangements, upfront disclosure of identity, training, good compliance records, and remuneration not significantly higher than other channels.', trap: 'MRTA is not exempt from the call-back safeguard even though some simple life policies ancillary to loans are.' },
    ],
  },
  {
    id: 'r11',
    num: 11,
    title: 'The Code on Collective Investment Schemes',
    page: 540,
    concepts: [
      { id: 'r11-01', term: 'Status of the CIS Code', fact: 'Issued by MAS under s 321 SFA, binding on managers, approved trustees, VCC directors and VCC custodians. It is non-statutory, so a breach is not itself a criminal offence, but it may be relied on in civil or criminal proceedings to establish or negate liability.', trap: 'Non-statutory does not mean toothless. MAS can revoke or suspend authorisation (s 286) or recognition (s 287) over a breach, and a trustee can lose its s 289 approval.' },
      { id: 'r11-02', term: 'Code revisions', fact: 'First issued 23 May 2002, last revised 23 May 2023. The 1 October 2011 revision introduced the permissible investments list, derivative and counterparty safeguards, standardised performance fees, fund naming principles, and the ban on simulated past performance data.', trap: 'MAS recognises a foreign scheme only if its investment guidelines are substantially similar to the revised Code.' },
      { id: 'r11-03', term: 'Independence of the trustee', fact: 'The trustee must be independent of the manager and deal at arm\'s length. Guidance: independence fails if any person holds 20% or more of the trustee\'s shares and also 20% or more of the manager\'s or its related corporations\' shares.', trap: 'The same 20% cross-shareholding test applies to a VCC custodian\'s independence from the VCC and the manager.' },
      { id: 'r11-04', term: 'Trustee reporting timelines', fact: 'Breach of s 289(3) SFA must be reported to MAS within 3 business days of awareness. Semi-annual accounts and report go to participants within 2 months of period end, annual accounts and report within 3 months of financial year end. Termination or maturity statements go to MAS within 2 weeks and are kept 6 years.', trap: 'Electronic reports must stay posted at least 12 months, and a participant requesting hardcopy must receive it within 2 weeks at no cost.' },
      { id: 'r11-05', term: 'Manager\'s core duties', fact: 'The manager must act per the constituent document and in participants\' best interest, transact at arm\'s length, obtain best execution under Notice SFA 04-N16, and must not act as counterparty to an OTC derivative the scheme invests in.', trap: 'The manager must not exercise significant influence over an issuer\'s management through the scheme.' },
      { id: 'r11-06', term: 'Related-party restrictions', fact: 'Scheme monies must not be invested in the manager\'s own securities or those of related corporations, unless they are constituents of an independently constructed reference benchmark. Lending scheme monies to related corporations is prohibited, though bank deposits do not count as lending.', trap: 'Real estate cannot be bought from the manager or its related corporations unless Appendix 6 permits it.' },
      { id: 'r11-07', term: 'Credit rating reliance', fact: 'No sole or mechanistic reliance on rating agencies. The manager must maintain internal credit assessment standards, and where external and internal ratings differ the lowest rating applies.', trap: 'The lowest rating governs, not an average and not the manager\'s own more favourable view.' },
      { id: 'r11-08', term: 'Redemption proceeds', fact: 'Redemption proceeds must be paid within T+7 business days, where T is the day a complete redemption request is received by the dealing cut-off. Proceeds are deemed paid when the account is credited or a cheque is mailed.', trap: 'Property funds follow Appendix 6 and hedge funds follow their prospectus, so the T+7 rule is not universal.' },
      { id: 'r11-09', term: 'Notification of significant changes', fact: 'Significant changes must be notified to MAS and participants at least 1 month before taking effect. These include a change in investment objective or approach, fee increases, a substantial increase in other charges meaning 0.1% or more of NAV, replacement of the manager or trustee, and a change to or from a feeder structure.', trap: 'The one-month notice applies even when the increased fee stays within the trust deed cap. Unforeseeable events such as suspensions are notified as soon as practicable instead.' },
      { id: 'r11-10', term: 'Rebates, soft dollars and expenses', fact: 'The manager must not retain cash or commission rebates from scheme transactions. Soft dollars may be retained only if they assist investment advice to the scheme, best execution is achieved and there is no churning. Marketing and promotion expenses cannot be paid from the scheme, but prospectus preparation, printing, lodgement and distribution costs can.', trap: 'Travel, accommodation and entertainment never qualify as soft dollar benefits.' },
      { id: 'r11-11', term: 'S$500 million delegation threshold', fact: 'Where more than 10% of NAV is sub-managed abroad, or more than 10% of NAV is invested in foreign-registered schemes, the manager together with its related corporations must already manage at least S$500 million of discretionary funds in Singapore.', trap: 'The threshold bites at more than 10% of NAV, and the S$500 million is measured across the manager and related corporations combined.' },
      { id: 'r11-12', term: 'Performance fees', fact: 'Performance fees must be equitable to all participants, calculated after all other payments, and crystallise no more than once a year. Only two methods are allowed without prior MAS consultation: the fulcrum fee, which moves symmetrically with performance against the benchmark and is bounded between zero and 200% of the base fee, and the high water mark, reset only when NAV reaches a new historical high at the end of a performance period.', trap: 'A 1.5% base fee gives a fulcrum fee range of 0% to 3.0%. The high water mark resets whether or not a fee actually crystallises.' },
      { id: 'r11-13', term: 'Scheme naming and prohibited activities', fact: 'A scheme name must not be undesirable or misleading, must not imply it is not a CIS by calling itself a plan or account, and the terms capital protected and principal protected are prohibited in any name or description. Schemes must not lend monies directly, grant guarantees, underwrite, or short sell except through financial derivatives under Appendix 1 sections 4 and 5.', trap: 'Fund-of-funds in the name is acceptable only if the scheme invests substantially all assets in five or more underlying funds.' },
      { id: 'r11-14', term: 'Dealing, valuation and suspension', fact: 'A scheme must deal at least one dealing day a month and publish the unit value at least once every dealing day. Suspension of dealing is only for exceptional circumstances in participants\' best interest, must be notified to participants and MAS immediately with reasons, and must end within 21 days unless the trustee is satisfied an extension serves participants, with weekly trustee review.', trap: 'Illiquidity alone may not justify suspension. Rounding differences from unit pricing or allotment are credited to the scheme, not kept by the manager.' },
      { id: 'r11-15', term: 'Valuation errors and compensation', fact: 'An NAV per unit error must be reported to MAS and the trustee as soon as practicable and every affected valuation date revalued. Where the error is 0.5% or more of NAV per unit, affected participants and the scheme must be compensated, with a de minimis exemption for a participant owed S$20 or less. Compensation costs cannot be charged to the scheme.', trap: 'The scheme must always be compensated even where individual participants fall under the S$20 de minimis. Below 0.5% no compensation is required, but if the manager compensates one participant it must compensate all on the same basis.' },
      { id: 'r11-16', term: 'Breach reporting and passive breaches', fact: 'Breaches must be rectified as soon as practicable with no transactions that increase the breach, and breaches of Part I or II guidelines reported to MAS within 3 business days of awareness. Passive breaches caused by price movement, redemptions, corporate capital changes, benchmark weight reduction or a ratings downgrade need no report if rectified within 3 months.', trap: 'The 3-month passive-breach grace period is extendable only if the trustee agrees it serves participants, subject to monthly review.' },
      { id: 'r11-17', term: 'Spread of investments limits', fact: 'Core Appendix 1 limits: 10% of NAV in a single entity, 20% for a group of entities. Government, agency or supranational paper rated at least BBB or Baa raises the single entity limit to 35% with a 20% cap per single issue, and paper rated at least AA or Aa has no single entity limit. Unrated or below investment grade corporate debt is cut to 5%.', trap: 'A downgrade below the qualifying rating pulls the limit straight back to the standard level. Concentration is separately capped at 10% of any single entity\'s outstanding shares.' },
      { id: 'r11-18', term: 'Global derivative exposure', fact: 'Global exposure to financial derivatives must not exceed 100% of NAV at all times, measured by the Commitment Approach or, with prior MAS consultation, a VaR Approach. Relative VaR is capped at 1.5x the reference portfolio\'s VaR and absolute VaR generally at 20% of NAV, using 99% one-tailed confidence, a 1-month holding period and a 1-year observation period.', trap: 'Back-testing exceptions are zoned: Green 0 to 4, Yellow 5 to 9 requiring investigation and remedies to MAS, Red 10 or more requiring positions to stop and wind down. Exceptions are notified to MAS within 3 business days.' },
    ],
  },
  {
    id: 'r12',
    num: 12,
    title: 'Securities Dealing - Market Conduct',
    page: 624,
    concepts: [
      { id: 'r12-01', term: 'Prohibited market conduct offences', fact: 'Part XII of the SFA prohibits false trading and market rigging (s.197), securities market manipulation (s.198), false or misleading statements (s.199), fraudulent inducement to trade (s.200), employment of manipulative and deceptive devices (s.201), dissemination of information about illegal transactions (s.202), and insider trading (ss.218 and 219).', trap: 'Candidates often mix up the section numbers: s.197 is false trading and market rigging, s.198 is market manipulation, and s.201 is manipulative and deceptive devices.' },
      { id: 'r12-02', term: 'Extraterritorial reach (s.196)', fact: 'Under s.196 SFA, the market conduct prohibitions apply to acts occurring in Singapore that affect markets outside Singapore, and to acts occurring outside Singapore that affect Singapore\'s markets.', trap: 'Being physically outside Singapore does not put a person beyond the reach of the SFA market conduct provisions.' },
      { id: 'r12-03', term: 'Wash sales and matched orders', fact: 'A wash sale is a transaction that involves no change in the beneficial ownership of the securities. Matched orders are buy and sell orders placed at substantially the same price and time by parties acting in collusion. Both create a false or misleading appearance of active trading.', trap: 'The defining feature of a wash sale is no change in beneficial ownership, not the size or price of the trade.' },
      { id: 'r12-04', term: 'Insider trading: connected vs non-connected persons', fact: 'Both connected and non-connected persons are prohibited from insider trading. For a connected person, the prosecution benefits from a rebuttable presumption that the person knew the information was price-sensitive and not generally available; for a non-connected person, the prosecution must prove that knowledge.', trap: 'The prohibition applies equally to both; only the evidential presumption of knowledge differs for connected persons.' },
      { id: 'r12-05', term: 'Generally available information (s.215)', fact: 'Information is generally available under s.215 SFA if it is readily observable, or has been made known in a manner likely to bring it to the attention of investors and a reasonable period for dissemination has elapsed, or it is derived from such information.', trap: 'Information announced to the exchange is not immediately generally available; a reasonable period for dissemination must first elapse.' },
      { id: 'r12-06', term: 'Insider trading exceptions and defences', fact: 'Sections 222 to 229 SFA set out exceptions to the insider trading prohibitions, s.231 provides the parity of information defence, and s.230 exempts a holder of a capital markets services licence (or its representative) who executes a client\'s order without knowledge of the inside information.', trap: 'The s.230 exemption protects the executing broker acting on a client\'s instructions, not the instructing insider.' },
      { id: 'r12-07', term: 'Civil penalty regime', fact: 'MAS may pursue market conduct contraventions through civil penalty actions instead of criminal prosecution. In one cited example, a civil penalty of S$2.9 million was imposed for insider trading.', trap: 'A civil penalty is a monetary sanction sought through the courts; it is not the same as a criminal fine or imprisonment.' },
      { id: 'r12-08', term: 'Securities hawking (s.309)', fact: 'Section 309 SFA prohibits offering securities for sale arising from an unsolicited meeting or telephone call (securities hawking). Offers made to institutional investors or accredited investors under ss.304 and 305 are exempted.', trap: 'The prohibition targets unsolicited offers to the public; offers to institutional and accredited investors are carved out.' },
      { id: 'r12-09', term: 'Covered vs uncovered short selling', fact: 'A covered short sale is one where the seller has borrowed the securities, or has a binding arrangement to borrow them, at the time of the sale. An uncovered (naked) short sale is made without owning the securities and without any borrowing arrangement in place.', trap: 'What makes a short sale naked is the absence of a borrowing arrangement at the time of sale, not merely the intention to profit from a price fall.' },
      { id: 'r12-10', term: 'CDP buying-in', fact: 'If a seller fails to deliver securities to settle a trade, the Central Depository (CDP) conducts a buying-in, purchasing the securities in the market on the defaulting seller\'s behalf and at the seller\'s cost.', trap: 'Buying-in is initiated by CDP against the failing deliverer; it is not an action taken by the buyer.' },
      { id: 'r12-11', term: 'Short sell order marking and short position reporting', fact: 'Under s.137ZJ SFA, sell orders that are short sells must be marked as such when placed. Under s.137ZK, short positions exceeding the prescribed threshold must be reported to MAS.', trap: 's.137ZJ deals with marking short sell orders; s.137ZK deals with reporting short positions. They are different obligations.' },
      { id: 'r12-12', term: 'Securities borrowing and lending collateral', fact: 'Under Regulation 45 of the SFR (Licensing and Conduct of Business), a borrower of specified products must provide the lender with collateral of at least 100% of the market value of the borrowed products. Collateral is not required where the lender is an accredited, expert or institutional investor.', trap: 'The 100% collateral requirement is waived only based on the status of the lender, not the borrower.' },
      { id: 'r12-13', term: 'Duties to clients', fact: 'A representative\'s duties to clients include loyalty, prudence and care, fair dealing, ensuring suitability of recommendations, fair and accurate presentation of performance, and preserving the confidentiality of client information.', trap: 'Suitability and confidentiality are duties owed to clients, distinct from the duties owed to the employer.' },
      { id: 'r12-14', term: 'Duties to employer', fact: 'Duties to the employer include loyalty, whistle-blowing on wrongdoing, and not accepting additional compensation or benefits that create a conflict with the employer\'s interests unless written consent is obtained from all parties involved.', trap: 'Additional outside compensation is not absolutely forbidden; it requires written consent from all parties involved.' },
    ],
  },
  {
    id: 'r13',
    num: 13,
    title: 'Central Provident Fund',
    page: 654,
    concepts: [
      { id: 'r13-01', term: 'CPF basics', fact: 'The CPF started on 1 July 1955 and is administered by the CPF Board under the Ministry of Manpower. CPF contributions are payable for Singapore Citizens and Permanent Residents earning more than S$50 per month, including part-time and casual employees.', trap: 'The wage threshold that triggers CPF contributions is more than S$50 per month, not S$500 or S$750.' },
      { id: 'r13-02', term: 'CPF contribution rates (from 1 Jan 2024)', fact: 'For monthly wages above S$750, the total contribution rate is 37% for employees aged 55 and below (17% employer + 20% employee), 31% for above 55 to 60, 22% for above 60 to 65, 16.5% for above 65 to 70, and 12.5% for above 70. Rates therefore range from 12.5% to 37%.', trap: 'The employee share for age 55 and below is 20% and the employer share is 17%; candidates often reverse the two.' },
      { id: 'r13-03', term: 'Self-employed contributions', fact: 'Self-employed persons are only required to contribute to MediSave, and only if their net trade income exceeds S$6,000 a year. MediSave contribution rates for the self-employed range from 4% to 10.5% depending on age and income.', trap: 'The self-employed have no compulsory Ordinary or Special Account contributions; only MediSave is mandatory.' },
      { id: 'r13-04', term: 'Retirement Sum Topping-Up tax relief', fact: 'Since 2022, a member can claim tax relief of up to S$8,000 per year for cash top-ups to his own Special or Retirement Account, and a further S$8,000 per year for cash top-ups to loved ones\' accounts, giving a maximum of S$16,000.', trap: 'The relief was raised from S$7,000 to S$8,000; each S$8,000 limit applies separately to own top-ups and to top-ups for loved ones.' },
      { id: 'r13-05', term: 'CPF interest rates and extra interest', fact: 'The Ordinary Account earns a floor rate of 2.5% per annum and the Special and MediSave Accounts earn a floor of 4% per annum, with rates reviewed quarterly. Members below 55 earn an extra 1% interest on the first S$60,000 of combined balances (capped at S$20,000 from the OA). Members 55 and above earn an extra 2% on the first S$30,000 and an extra 1% on the next S$30,000 of combined balances (also with a S$20,000 OA cap).', trap: 'The extra interest OA cap is S$20,000; the extra 2% tier applies only to members aged 55 and above.' },
      { id: 'r13-06', term: 'CPF Investment Scheme (CPFIS)', fact: 'To invest under CPFIS a member must be at least 18, not an undischarged bankrupt, and may only invest OA savings in excess of S$20,000 and SA savings in excess of S$40,000. From 1 Oct 2018, new CPFIS investors must first complete the Self-Awareness Questionnaire (SAQ).', trap: 'The first S$20,000 in the OA and first S$40,000 in the SA cannot be invested; only the excess can.' },
      { id: 'r13-07', term: 'Retirement sums (BRS, FRS, ERS)', fact: 'The Full Retirement Sum is set at 2 times the Basic Retirement Sum. From 2025 the Enhanced Retirement Sum was raised from 3 times to 4 times the BRS. For the 2026 cohort the BRS is S$110,200, the FRS is S$220,400 and the ERS is S$440,800; the BRS rises by about 3.5% per cohort from 2023 to 2027.', trap: 'The ERS multiple changed from 3x BRS to 4x BRS from 2025; using the old 3x multiple gives the wrong figure.' },
      { id: 'r13-08', term: 'CPF LIFE auto-inclusion and payout age', fact: 'Members are automatically included in CPF LIFE if they are Singapore Citizens or PRs born in 1958 or after and have at least S$60,000 in their Retirement Account when their payouts are due to start. Payouts can start any time between 65 and 70, and deferring increases payouts by up to 7% for each year of deferral; payouts start automatically at 70.', trap: 'Auto-inclusion needs both conditions: born 1958 or later and at least S$60,000 in the RA at payout start.' },
      { id: 'r13-09', term: 'CPF LIFE plans', fact: 'CPF LIFE offers the Standard Plan (the default, with level payouts), the Escalating Plan (payouts start lower but rise by 2% each year), and the Basic Plan (a legacy plan whose payouts fall when combined CPF balances drop below S$60,000).', trap: 'The default plan is the Standard Plan, not the Basic Plan; the Escalating Plan\'s payouts increase by 2% per year.' },
      { id: 'r13-10', term: 'CPF withdrawals from 55 and 65', fact: 'From age 55, a member can unconditionally withdraw up to S$5,000 even if he cannot set aside his retirement sum. From age 65, members born in 1958 or after can additionally withdraw up to 20% of their retirement savings, less the S$5,000 already withdrawable from 55.', trap: 'The 20% withdrawable from 65 is inclusive of the S$5,000 available from 55, not on top of it.' },
      { id: 'r13-11', term: 'Matched Retirement Savings Scheme (MRSS)', fact: 'MRSS was launched in 2021 with the Government matching cash top-ups dollar-for-dollar up to S$600 per year. From 1 Jan 2025, the annual matching cap is raised to S$2,000 with a S$20,000 lifetime cap, and the upper age limit is removed so all eligible members aged 55 and above qualify. Givers do not receive tax relief on top-ups that attract the matching grant.', trap: 'From 2025 there is no upper age limit for MRSS, and matched top-ups no longer earn the giver tax relief.' },
      { id: 'r13-12', term: 'MediSave, BHS and MediShield Life', fact: 'The Basic Healthcare Sum (BHS) is S$71,500 in 2024 and is fixed for a member once he reaches age 65. MediShield Life became compulsory for all Singapore Citizens and PRs from 1 Nov 2015, and MediFund was set up in April 1993 as an endowment fund safety net.', trap: 'The BHS is adjusted yearly only until age 65, after which it is fixed for that member for life.' },
      { id: 'r13-13', term: 'CareShield Life vs ElderShield', fact: 'CareShield Life replaced ElderShield for cohorts born in 1980 or later and pays monthly benefits starting at S$600 in 2020, increasing yearly until age 67 or the first claim. Severe disability means being unable to perform at least 3 of the 6 activities of daily living: washing, dressing, feeding, toileting, mobility and transferring. The Government took over ElderShield administration on 1 Nov 2021.', trap: 'The claim trigger is failing at least 3 of 6 ADLs, not 2 of 6.' },
      { id: 'r13-14', term: 'Dependants\' Protection Scheme (DPS)', fact: 'DPS is a term insurance scheme administered solely by Great Eastern Life, covering members aged 21 to 65. The maximum sum assured is S$70,000 up to age 60 and S$55,000 from above 60 to 65, with a minimum of S$5,000.', trap: 'DPS cover steps down to S$55,000 after age 60; it does not stay at S$70,000 until 65.' },
      { id: 'r13-15', term: 'Home Protection Scheme (HPS)', fact: 'HPS is a mortgage-reducing term insurance scheme that insures members up to age 65 or until the housing loan is paid off, whichever is earlier. It applies to public housing only (not private property, ECs or privatised HUDC flats) and is compulsory for members using CPF savings to pay their monthly housing instalments.', trap: 'HPS covers HDB flats only; private property buyers cannot be covered under HPS even if they use CPF.' },
      { id: 'r13-16', term: 'CPF nomination', fact: 'CPF savings do not form part of a member\'s estate and cannot be distributed by will. With a valid nomination, distribution takes about 17 working days; without one, the savings go to the Public Trustee\'s Office for distribution under intestacy law, which can take up to 6 months and incurs a fee. A nomination is revoked upon marriage.', trap: 'Marriage revokes an existing CPF nomination; divorce does not automatically do so.' },
    ],
  },
  {
    id: 'r14',
    num: 14,
    title: 'Why Professional Ethics Matter',
    page: 693,
    concepts: [
      { id: 'r14-01', term: 'Ethics vs compliance', fact: 'Compliance means observing the letter of the law and regulations; ethics goes further and honours the spirit and intent behind the rules. An act can be perfectly legal yet still unethical, so a representative must go beyond mere compliance.', trap: 'Legal does not mean ethical: satisfying every regulation does not guarantee the conduct was ethical.' },
      { id: 'r14-02', term: 'Financial services and trust', fact: 'Financial services contribute more than 15% of Singapore\'s GDP, with more than 15,000 financial institutions operating here. The industry runs on trust: clients hand over money today in exchange for promises of future benefits, so ethical conduct is essential to preserve confidence in the industry.', trap: 'The figures are more than 15% of GDP and more than 15,000 financial institutions - two different \'15\' figures that are easily confused.' },
      { id: 'r14-03', term: 'MAS enforcement outcomes', fact: 'In the 18 months to June 2020, MAS enforcement actions included 9 criminal convictions, 25 prohibition orders, S$11.7 million in civil penalties and S$3.4 million in financial penalties and compositions, alongside reprimands, warnings, letters of advice and supervisory reminders.', trap: 'S$11.7 million was in civil penalties while S$3.4 million was in financial penalties and compositions - do not swap the two.' },
      { id: 'r14-04', term: 'The trust equation', fact: 'Charles H. Green\'s trust equation states: Trust = (Credibility + Reliability + Intimacy) / Self Interest. Because self interest sits in the denominator, the more self-interested an adviser appears, the lower the client\'s trust.', trap: 'Self interest divides the equation; it is not one of the three factors that are added together.' },
      { id: 'r14-05', term: 'Multiple motivations', fact: 'People rarely act from a single motive. Behaviour is driven by a mix of self-interested motivation, motivation based on affection for others, and moral motivation to do what is right; ethical failure often occurs when self-interest overwhelms the others.', trap: 'Self-interest by itself is not unethical; problems arise when it is pursued at the expense of moral and other motivations.' },
      { id: 'r14-06', term: 'Pressures toward unethical conduct', fact: 'Rationalisation, peer pressure and monetary incentives can push representatives into unethical acts. In a 2011 case cited in the text, an agent sold about S$6.2 million worth of fake policies, illustrating how incentive pressure and rationalisation can escalate into fraud.', trap: 'Rationalisation means inventing excuses to justify wrongdoing, such as \'everyone does it\' - it does not make the act any less wrong.' },
    ],
  },
  {
    id: 'r15',
    num: 15,
    title: 'Professionalism',
    page: 704,
    concepts: [
      { id: 'r15-01', term: 'Four characteristics of a professional', fact: 'A professional displays: mastery of a particular subject matter, reliability, management of self-interest, and a spirit of loyalty to fellow representatives.', trap: 'Management of self-interest means keeping it in check, not eliminating it; and loyalty here refers to fellow representatives, not only to clients.' },
      { id: 'r15-02', term: 'Basic requirements of a profession', fact: 'A profession is marked by prolonged academic study, barriers to entry, independence in judgement, public recognition, a governing authority, professional societies, and a code of ethics.', trap: 'High income is not one of the hallmarks of a profession; a code of ethics and entrance barriers are.' },
      { id: 'r15-03', term: 'MAS Notice FAA-N26', fact: 'MAS Notice FAA-N26 sets out the minimum entry and examination (competency) requirements that a person must meet before acting as an appointed representative providing financial advisory services.', trap: 'FAA-N26 deals with competency and entry requirements; FAA-N16 deals with recommendations, and FAA-N03 with information to clients.' },
      { id: 'r15-04', term: 'Client expectations of a professional', fact: 'Clients expect a representative to listen, answer questions, gather sufficient information, educate them, consider their risk knowledge, hold proper credentials, provide ongoing service, handle money properly (a representative should not collect cash directly from clients), refer them to experts where a matter is beyond his expertise, and stay current in knowledge.', trap: 'Handling money properly means not collecting cash directly from clients; premium payments should go to the insurer, not into the representative\'s hands.' },
      { id: 'r15-05', term: 'Definition of representative (FAA s.2(1))', fact: 'Under s.2(1) FAA, a representative is a person who acts as a representative in respect of any financial advisory service, or holds himself out as doing so, in the direct employment of, or under an arrangement with, a financial adviser.', trap: 'Holding oneself out as a representative is enough to fall within the definition, even without actually giving advice.' },
      { id: 'r15-06', term: 'One-principal rule (FAA s.27(1))', fact: 'Under s.27(1) FAA, a representative may act as representative for only one principal, unless the principals are related corporations. The objectives are close supervision of the representative and clarity of responsibility for his conduct.', trap: 'The exception to the one-principal rule applies only where the principals are related corporations.' },
    ],
  },
  {
    id: 'r16',
    num: 16,
    title: 'Ethical Behavior',
    page: 713,
    concepts: [
      { id: 'r16-01', term: 'LIA core values', fact: 'The Life Insurance Association\'s core values are: Unified, Professional, Ethical, Fair, Open and honest, and Proactive. Industry bodies such as IMAS similarly require integrity, professionalism, competence and due diligence in their codes.', trap: 'The LIA values include being Proactive and Unified - words like \'profitable\' or \'competitive\' are not among them.' },
      { id: 'r16-02', term: 'Seven principles of ethical behaviour', fact: 'The seven principles of ethical behaviour for representatives are: Integrity, Objectivity, Competence, Fairness, Confidentiality, Professionalism and Diligence.', trap: 'Profitability and obedience are not among the seven principles; confidentiality and diligence are.' },
      { id: 'r16-03', term: 'Integrity', fact: 'Integrity comes from the Latin \'integer\', meaning whole, entire and undiminished. It denotes wholeness of character: being honest and consistent in all dealings, in public and in private.', trap: 'Integrity is about wholeness and consistency of character, not merely about not breaking the law.' },
      { id: 'r16-04', term: 'Objectivity and its obstacles', fact: 'Objectivity requires basing advice on facts and the client\'s circumstances. Its two main obstacles are cognitive bias - especially confirmation bias, the tendency to notice only information that confirms what we already believe - and conflicts of interest.', trap: 'Confirmation bias is about seeking confirming evidence; it is not the same as a conflict of interest, which stems from misaligned incentives.' },
      { id: 'r16-05', term: 'Competence', fact: 'Competence must first be attained and then maintained through continuing professional development, since products, rules and markets keep changing. A representative should act only within his own expertise and refer the client to other experts for matters outside it.', trap: 'Competence is not a one-off achievement at licensing; it must be maintained through CPD.' },
      { id: 'r16-06', term: 'Fairness', fact: 'Fairness means treating like things in like ways (equality), following the Golden Rule of treating others as you wish to be treated, and giving each party what is due. A representative must be fair to multiple stakeholders, including clients, the principal, fellow representatives and the industry.', trap: 'Fairness extends beyond clients to other stakeholders such as the employer, colleagues and the industry.' },
      { id: 'r16-07', term: 'Confidentiality and the PDPA', fact: 'The Personal Data Protection Act 2012 protects client data. Individuals who breach it can be fined up to S$5,000 and/or jailed up to 2 years, while organisations face financial penalties of up to S$1 million or 10% of gross annual Singapore turnover, whichever is higher.', trap: 'The 10% of turnover cap applies to organisations; the S$5,000 fine and possible jail term apply to individuals.' },
      { id: 'r16-08', term: 'Professionalism, diligence and the payoff', fact: 'Professionalism means never treating people as mere means to an end, and bringing trust and dignity to every interaction. Diligence means prompt and thorough service with painstaking due care, without over promising and under delivering. Ethical behaviour brings client loyalty, a good reputation, employee retention, a positive environment and fewer legal problems.', trap: 'The classic diligence failure is to over promise and under deliver - the ethical practice is the reverse.' },
    ],
  },
  {
    id: 'r17',
    num: 17,
    title: 'Unethical Behavior',
    page: 727,
    concepts: [
      { id: 'r17-01', term: 'Churning', fact: 'Churning is inducing a client to terminate policies after a short period and switch to similar products, generating fresh commissions for the representative while giving the client no real benefit and often causing him loss.', trap: 'The gain from churning accrues to the representative through commissions; the client typically loses out.' },
      { id: 'r17-02', term: 'The 2015 mis-selling case', fact: 'A Straits Times report of 5 Oct 2015 described a divorcee who deposited about S$350,000 of divorce settlement money and was sold a policy with an annual premium of about S$40,000 - exceeding her annual income - a clear example of unsuitable, unethical selling.', trap: 'The red flag in the case was an annual premium exceeding the client\'s annual income, not merely a large single deposit.' },
      { id: 'r17-03', term: 'Range of unethical behaviours', fact: 'The text lists 22 types of unethical behaviour by representatives, covering areas such as misrepresentation of products, unsuitable recommendations, improper handling of client money and documents, and placing personal interest above the client\'s.', trap: 'Unethical behaviour is broader than illegal behaviour - many of the listed practices may not attract prosecution but still breach ethics.' },
      { id: 'r17-04', term: 'Four obstacles to ethical decision making', fact: 'The four obstacles to ethical decision making are: corrupted character, lack of moral perception, giving in to temptation, and rationalization.', trap: 'Lack of moral perception means failing to even recognise that a situation raises an ethical issue - different from seeing the issue and yielding to temptation.' },
      { id: 'r17-05', term: 'Rationalization', fact: 'Rationalization is constructing seemingly plausible excuses to justify unethical conduct, such as \'everyone does it\' or \'the client can afford the loss\'. It allows a person to act wrongly while preserving his self-image.', trap: 'Rationalization happens after or alongside the wrongful choice to excuse it; it does not convert a wrong act into a right one.' },
    ],
  },
  {
    id: 'r18',
    num: 18,
    title: 'Conflict Of Interest',
    page: 732,
    concepts: [
      { id: 'r18-01', term: 'Conflict of interest: definition and two types', fact: 'A conflict of interest exists when the interests or objectives of two parties are incompatible or misaligned. A representative may find himself in a conflict that is built into the business arrangement, or he may create a conflict through his own actions.', trap: 'Built-in conflicts (found) and self-created conflicts are treated as two distinct types.' },
      { id: 'r18-02', term: 'Five misalignments of interests', fact: 'Conflicts can arise from five misalignments: between the representative and the client; among the financial institution, the representative and the client; between the financial institution and the client; between the representative and multiple clients; and between the financial institution and multiple clients.', trap: 'Conflicts are not only rep-versus-client; the institution itself and multiple clients can be parties to a conflict.' },
      { id: 'r18-03', term: 'Six manifestations of conflict', fact: 'Conflicts of interest manifest as: biased advice, involuntary cross-selling, excessive trading (churning and twisting), failure to execute, insufficient or misleading disclosure, and violation of privacy or confidentiality.', trap: 'Failure to execute a client\'s instruction is itself a manifestation of conflict of interest, not just poor service.' },
      { id: 'r18-04', term: 'Involuntary cross-selling', fact: 'Involuntary cross-selling happens in two ways: the client is forced to buy a bundled product he does not want in order to obtain the product he does want, or the client is placed into a disadvantageous default option.', trap: 'Cross-selling per se is not unethical; it becomes so when the client is forced (bundling) or defaulted into it involuntarily.' },
      { id: 'r18-05', term: 'Churning vs twisting', fact: 'Churning is making a client replace a policy with a new one from the SAME insurer, while twisting is replacement with a policy from ANOTHER insurer. Both are driven by commissions, often where the representative exercises de facto discretionary control over the client\'s decisions.', trap: 'Same insurer = churning; different insurer = twisting. The distinguishing feature is which insurer issues the replacement policy.' },
      { id: 'r18-06', term: 'Misleading illustrations', fact: 'Insufficient or misleading disclosure includes unrealistic policy illustrations. The \'vanished premiums\' scandals led the US NAIC to issue the Life Insurance Illustrations Model Regulation in 1995 to curb misleading projections.', trap: 'The NAIC Life Insurance Illustrations Model Regulation dates from 1995 and responded to the \'vanished premiums\' problem.' },
      { id: 'r18-07', term: 'Fiduciary standard', fact: 'The fiduciary standard is principles-based and requires acting in the client\'s best interest, observing the duties of Care, Loyalty, Obedience and Good Faith.', trap: 'The fiduciary duties are Care, Loyalty, Obedience and Good Faith - suitability is a separate, rules-based standard.' },
      { id: 'r18-08', term: 'Suitability standard and best interest', fact: 'The suitability standard is rules-based: s.36 FAA requires a reasonable basis for recommendations, and FAA-N16 requires knowing your client, needs analysis and documentation. A CKA applies to unlisted Specified Investment Products and a Customer Account Review to listed SIPs. A suitable recommendation is not necessarily in the client\'s best interest - a representative could pick the highest-commission product among several suitable ones.', trap: 'Suitable is not the same as best: the suitability standard can be met while still favouring the product that pays the representative most.' },
    ],
  },
  {
    id: 'r19',
    num: 19,
    title: 'Fair Dealing',
    page: 745,
    concepts: [
      { id: 'r19-01', term: 'Fairly does not mean equally', fact: 'Dealing fairly with clients means treating each client appropriately according to his circumstances; it does not mean treating every client identically.', trap: 'Fair treatment can legitimately differ between clients - identical treatment of clients with different needs can itself be unfair.' },
      { id: 'r19-02', term: 'Three core fair dealing principles', fact: 'Fair dealing rests on three core principles: clear allocation of roles and responsibilities, transparency, and management of conflicts of interest (including third-party compensation).', trap: 'Transparency is one of three principles; disclosure alone without managing conflicts does not amount to fair dealing.' },
      { id: 'r19-03', term: 'Six key areas of transparency', fact: 'Transparency to clients covers six key areas of a product: features, performance, benefit, risk, fees and charges, and special features.', trap: 'The representative\'s own sales targets or commission structure ranking is not one of the six transparency areas; fees and charges of the product are.' },
      { id: 'r19-04', term: 'MAS Guidelines FAA-G11', fact: 'The MAS Guidelines on Fair Dealing (FAA-G11) place the responsibility for delivering fair dealing outcomes squarely on the Board and Senior Management of the financial institution.', trap: 'Responsibility under FAA-G11 sits with the Board and Senior Management, not only with front-line representatives.' },
      { id: 'r19-05', term: 'Five fair dealing outcomes', fact: 'The five fair dealing outcomes are: (1) fair dealing is central to the corporate culture; (2) products offered are suitable for the target client segments; (3) representatives are competent and give quality advice and recommendations; (4) clients receive clear, relevant and timely information; and (5) complaints are handled in an independent, effective and prompt manner.', trap: 'Outcome 5 requires complaints handling that is independent, effective and prompt - all three qualities, not just speed.' },
    ],
  },
  {
    id: 'r20',
    num: 20,
    title: 'Ethical Marketing & Sale Of Financial Products',
    page: 752,
    concepts: [
      { id: 'r20-01', term: 'Six steps of an ethically sound sales process', fact: 'An ethically sound sales process: gains the client\'s attention, explains the product structure, explains the downside risk, clarifies the coverage components, explains who bears the risk, and complies with all applicable rules.', trap: 'Explaining downside risk and who bears the risk are compulsory steps, not optional extras for interested clients.' },
      { id: 'r20-02', term: 'Who bears the risk', fact: 'In a participating or investment-linked policy, the client bears the risk of the non-guaranteed elements (bonuses and investment returns), while the insurer bears the risk of the guaranteed benefits.', trap: 'Non-guaranteed bonuses and investment returns are at the client\'s risk, not the insurer\'s.' },
      { id: 'r20-03', term: 'Three sales pitfalls', fact: 'The three main pitfalls in selling are misrepresentation, recommending unsuitable products, and conflict of interest.', trap: 'These are pitfalls of the sales process; bogus qualifications and scare tactics belong to the separate list of marketing pitfalls.' },
      { id: 'r20-04', term: 'Misrepresentation vs fraud', fact: 'Fraud requires intentional deception. Misrepresentation can be unintentional, negligent, or arise from an omission, and can still attract liability - the UK Misrepresentation Act 1967 framework is cited. A representative can misrepresent without intending to deceive.', trap: 'Intent separates fraud from mere misrepresentation; a false statement made carelessly is still misrepresentation even without intent to deceive.' },
      { id: 'r20-05', term: 'Holley\'s five disclosure strategies', fact: 'Holley\'s five information disclosure strategies are: Minimal Information (caveat emptor), Modified Minimal Information (adds safety information), the Fairness Rule, the Mutual Benefit Rule, and the Maximal Information Rule. The text suggests going further with a \'Mutual Benefit Rule Plus\'.', trap: 'Minimal Information corresponds to caveat emptor (buyer beware); the Maximal Information Rule discloses the most.' },
      { id: 'r20-06', term: 'FAA-N03 disclosure', fact: 'MAS Notice FAA-N03 (Information to Clients and Product Information Disclosure) requires written disclosure to clients, including disclosure of conflicts of interest, the representative\'s status and remuneration, and product information.', trap: 'Conflict disclosure under FAA-N03 must be in writing; a verbal mention is not sufficient.' },
      { id: 'r20-07', term: 'Three marketing pitfalls', fact: 'The three marketing pitfalls are: using bogus qualifications or designations, scare tactics (such as doomsday examples), and creating unrealistic expectations of returns or benefits.', trap: 'Scare tactics involve exaggerated doomsday scenarios; presenting realistic risk information is not a scare tactic.' },
    ],
  },
  {
    id: 'r21',
    num: 21,
    title: 'Developing Client - Representative Relationships',
    page: 767,
    concepts: [
      { id: 'r21-01', term: 'Delivery of policy documents', fact: 'Under item 3.3 of the LIA Code of Life Insurance Practice, a new policy document should be delivered to the policyholder within 30 days from policy issuance.', trap: 'The 30-day delivery window runs from policy issuance, and the duty comes from the LIA Code, not the FAA.' },
      { id: 'r21-02', term: 'Persuasion vs coercion', fact: 'Persuasion gives the client reasons and respects his freedom to choose; coercion pressures or threatens the client into a decision. Persuasion is a legitimate interacting skill; coercion is unethical.', trap: 'The dividing line is the client\'s freedom to say no - remove that freedom and persuasion becomes coercion.' },
      { id: 'r21-03', term: 'Four steps for handling conflicts with clients', fact: 'When a conflict or complaint arises: (1) recognise the client\'s feelings; (2) empathise and apologise; (3) determine the facts; and (4) find a solution. Feelings are addressed first, before the facts.', trap: 'Deal with feelings first and facts second - jumping straight to the facts is the classic mistake.' },
      { id: 'r21-04', term: 'Definition of a complaint', fact: 'A complaint is any oral or written expression of dissatisfaction, whether justified or not. Every complaint should be taken seriously and handled through a problem-solving approach.', trap: 'A complaint need not be in writing and need not be justified to count as a complaint.' },
      { id: 'r21-05', term: 'Post-sale review timeline', fact: 'Reviews after a sale should be conducted at around 3 months, 12 months and 18 months, and should be carried out by a qualified representative rather than left to the client service office.', trap: 'The post-sale reviews are the representative\'s job; routing them to the client service office does not discharge the duty.' },
      { id: 'r21-06', term: 'Conditions for good listening', fact: 'Dr Thomas Gordon identified the conditions for good listening as acceptance, empathy and genuineness on the part of the listener.', trap: 'Gordon\'s three conditions are acceptance, empathy and genuineness - agreement with the speaker is not required.' },
    ],
  },
  {
    id: 'r22',
    num: 22,
    title: 'Fact Finding And Needs Analysis',
    page: 788,
    concepts: [
      { id: 'r22-01', term: 'Prime objective of fact-finding', fact: 'The prime objective of fact-finding and needs analysis is to identify the client\'s needs, quantify the total amount required for each need, take stock of existing provisions, and establish the shortfall to be covered.', trap: 'Quantifying the shortfall requires deducting existing provisions - recommending the full quantified need double-counts what the client already has.' },
      { id: 'r22-02', term: 'FAA-N16 three requirements', fact: 'MAS Notice FAA-N16 imposes three requirements on the advisory process: know your client, needs analysis, and documentation of the basis of recommendations.', trap: 'FAA-N16 covers the advisory process (KYC, needs analysis, documentation); disclosure to clients is FAA-N03.' },
      { id: 'r22-03', term: 'LIA minimum standard (MU 20/15)', fact: 'LIA circular MU 20/15 sets the Minimum Standard for the Life Insurance Advisory Process, effective no later than 1 April 2015. It applies to life policies and accident and health policies, but NOT to personal accident insurance.', trap: 'Personal accident insurance is excluded from the LIA minimum standard even though other A&H policies are covered.' },
      { id: 'r22-04', term: 'Advisory Form sections', fact: 'The prescribed Advisory Form covers: general information, know your client, needs analysis, recommendation(s), replacement of policy, declarations, and the supervisor\'s review.', trap: 'The supervisor\'s review is a formal section of the Advisory Form, not an optional internal step.' },
      { id: 'r22-05', term: 'Trusted Individual', fact: 'A client should be accompanied by a Trusted Individual if he meets any TWO of: aged 62 or above, not proficient in spoken or written English, and educated to secondary level or below. The Trusted Individual must be at least 18, educated to at least GCE N or O Level, proficient in English, and trusted by the client.', trap: 'The trigger is meeting any TWO of the three criteria, not all three and not just one.' },
      { id: 'r22-06', term: 'Needs quantification rules of thumb', fact: 'Common planning assumptions: support children up to age 25 for boys and age 22 for girls; life expectancy of 80 for females and 75 for males; and a rule of thumb of providing about 8 years of support for dependent parents.', trap: 'The support ages differ: 25 for sons and 22 for daughters; and the 8-year rule applies to parents, not children.' },
      { id: 'r22-07', term: 'CKA and investment risk profile', fact: 'The Customer Knowledge Assessment for unlisted Specified Investment Products is passed by meeting any ONE of: a diploma or higher qualification in a listed relevant field; at least 6 transactions in collective investment schemes or ILPs in the last 3 years; or at least 3 consecutive years of relevant working experience in the past 10 years. Section 4a (Investment Risk Profile) must be completed for products with a cash value.', trap: 'Passing the CKA requires only ONE of the three criteria; the 3 years of work experience must be consecutive and within the past 10 years.' },
      { id: 'r22-08', term: 'Financial position facts', fact: 'Fact-finding covers seven areas including life stage, employment, dependants, financial position, existing insurance, investment profile and priorities. Disability income cover is typically limited to about 75% of income, and the net asset position equals assets minus liabilities - a negative figure means the client is effectively bankrupt.', trap: 'Disability income insurance replaces only about 75% of income, not 100%, to preserve the incentive to return to work.' },
    ],
  },
  {
    id: 'r23',
    num: 23,
    title: 'Analysing And Evaluating A Client\'s Financial Status',
    page: 827,
    concepts: [
      { id: 'r23-01', term: 'Balance sheet vs income statement', fact: 'The balance sheet (statement of net worth) shows a person\'s assets, liabilities and net worth at a specific point in time. The income statement (statement of cash flows) shows income against expenditure over a period, usually one year.', trap: 'The balance sheet is a point-in-time snapshot; the income statement covers a period. Mixing up the two is a classic error.' },
      { id: 'r23-02', term: 'Three categories of assets', fact: 'Assets fall into liquid assets (cash and near-cash convertible within about one year), investment assets (held for long-term objectives, e.g. shares, bonds, unit trusts, CPF savings) and personal assets (for consumption, e.g. car, home, watch). Classification depends on why the asset was acquired and how it will be used - an antique car held for capital gain is an investment asset.', trap: 'The same asset can sit in different categories depending on intention: a money market fund kept for retirement is an investment asset, not a liquid asset.' },
      { id: 'r23-03', term: 'Emergency funds guideline', fact: 'Set aside at least 3 to 6 months\' worth of expenses as emergency funds; a person with irregular income should aim for 12 months of expenses. Budgeting should separate essentials from good-to-haves.', trap: 'The 12-month emergency fund target applies to irregular income earners; 3 to 6 months is the standard guideline.' },
      { id: 'r23-04', term: 'Valuation of assets and liabilities', fact: 'Assets are reported at current fair market value, though hard-to-value assets may conservatively be shown at original cost. Liabilities are reported at the outstanding principal - interest payments do not reduce the reported liability, only principal repayments do.', trap: 'Only the principal portion of a loan instalment reduces the liability on the balance sheet; the interest portion does not.' },
      { id: 'r23-05', term: 'Net worth', fact: 'Net worth = total assets - total liabilities. In the text\'s example, George\'s net worth is S$310,000 - S$131,000 = S$179,000. It is the bottom-line amount left if all assets were sold and all debts repaid.', trap: 'A person with expensive assets can still have a low net worth if they are heavily mortgaged - always deduct liabilities.' },
      { id: 'r23-06', term: 'Cash surplus and deficit', fact: 'Net cash flow = total inflows - total outflows, and can be positive (surplus), negative (deficit) or zero. A surplus can fund savings, investments or debt reduction, but a surplus does not necessarily mean the funds are ready for use - its disposition is reflected in the assets, liabilities and net worth.', trap: 'A cash surplus is not automatically spendable cash; it may already be locked into assets or debt repayment.' },
      { id: 'r23-07', term: 'Liquidity ratios', fact: 'Liquidity ratio = liquid assets / monthly expenses, showing the number of months of expenses covered; the guideline is at least 3 to 6 months. Liquid assets to net worth ratio = liquid assets / net worth, with a guideline of at least 15%.', trap: 'The liquidity ratio divides by MONTHLY expenses and is expressed in months; the liquid-assets-to-net-worth ratio is a percentage of net worth.' },
      { id: 'r23-08', term: 'Savings, debt-to-asset and debt service ratios', fact: 'Savings ratio = savings and investments / total income, guideline at least 10%. Debt-to-asset ratio = total liabilities / total assets, guideline at most 50%. Debt service ratio = annual loan payments / annual take-home pay, guideline at most 35%.', trap: 'The debt service ratio uses take-home pay in the denominator and loan payments in the numerator - it is not liabilities over assets.' },
      { id: 'r23-09', term: 'Investment assets to net worth and solvency ratios', fact: 'Investment assets to net worth ratio = investment assets / net worth, guideline at least 50%, and it should increase as a person ages. Solvency ratio = net worth / total assets, showing how much of the assets the person owns outright; when liabilities exceed assets, net worth is negative and the person is technically insolvent.', trap: 'The solvency ratio is net worth over total assets - it is the complement of the debt-to-asset ratio, and the two must sum to 100%.' },
    ],
  },
  {
    id: 'r24',
    num: 24,
    title: 'Developing Appropriate Strategies And Solutions',
    page: 837,
    concepts: [
      { id: 'r24-01', term: 'Two basic principles of recommendation', fact: 'Before recommending any product: (a) recommend products only if the client needs them, and (b) recommend only the products most suitable for the client given his circumstances.', trap: 'Need comes first - even a suitable product should not be recommended if the client has no need for it.' },
      { id: 'r24-02', term: 'Product knowledge checklist', fact: 'A representative must know each product\'s range, purpose, nature (participating, non-participating or investment-linked), cash value and bonuses, special features (e.g. convertibility, guaranteed renewability), benefit triggers, risks and who bears them, distribution costs and charges, duration of cover, premium terms, consequences of non-payment, the 14-day free-look provision, and medical/non-medical limits.', trap: 'The free-look period is 14 days - a product feature the representative must be able to explain.' },
      { id: 'r24-03', term: 'Insurance creates an immediate estate', fact: 'Insurance is the most suitable product for protection needs because it creates an immediate estate: the full sum assured is payable on the insured event even if only one premium has been paid. Clients aged 55 or above should review their insurance plans every 2 to 3 years to ensure they remain affordable.', trap: 'Savings take time to accumulate and stop at death or disability; only insurance pays the full sum assured from day one.' },
      { id: 'r24-04', term: 'Recommended protection coverage', fact: 'The Basic Financial Planning Guide recommends coverage of 9 times annual income for death and total permanent disability and 4 times annual income for standard critical illness. The Dependants\' Protection Scheme provides up to S$70,000 cover until age 60 and up to S$55,000 from above 60 to 65, automatically extended to citizens and PRs aged 21 to 65 on their first CPF working contribution.', trap: '9x annual income is for death and TPD; 4x is for critical illness - do not reverse the multiples.' },
      { id: 'r24-05', term: 'Affordability guide', fact: 'Spend at most 15% of income (after deducting CPF contributions) on insurance protection - bundled products may exceed 15% as they contain both investment and protection elements - and invest at least 10% of income for retirement and other financial goals. Early lapses hurt everyone: the client loses cover and premiums, the representative loses goodwill and commissions, and the insurer absorbs the initial costs.', trap: 'The 15% cap and 10% floor are both measured on income after deducting CPF contributions.' },
      { id: 'r24-06', term: 'Riders', fact: 'Riders (supplementary benefits) are special provisions attached to a basic policy that add benefits not in the basic contract. Common riders include waiver of premium, TPD, critical illness, term, payor benefit, guaranteed insurability option, accidental death benefit, accidental death and dismemberment, and hospital cash benefit riders.', trap: 'A rider cannot stand alone - it must ride on a basic policy such as a term or whole life plan.' },
      { id: 'r24-07', term: 'Prioritisation of needs', fact: 'Where a client cannot afford to meet all needs at once, help him prioritise. Where there are dependants, protection needs should generally be met first. A client wanting permanent cover he cannot yet afford can take a convertible term policy and convert it later when finances improve.', trap: 'A convertible term policy lets the client convert to permanent cover later, usually without fresh evidence of health.' },
      { id: 'r24-08', term: 'Estate and legacy planning; aborting a sale', fact: 'Legacy planning covers a will (distribution of estate), a CPF nomination (distribution of CPF savings), a Lasting Power of Attorney (appointing trusted persons to decide if mental capacity is lost) and an Advance Care Plan (future health and personal care wishes). If the adviser doubts the client understands critical product features - especially a client who fails the CKA - he should consider aborting or declining the sale.', trap: 'CPF savings are not distributed by will; they require a separate CPF nomination.' },
    ],
  },
  {
    id: 'r25',
    num: 25,
    title: 'Presentation Of Analysis And Solutions To Clients',
    page: 846,
    concepts: [
      { id: 'r25-01', term: 'Systematic presentation sequence', fact: 'Present recommendations systematically: state the purpose of the product (the need it meets), describe its nature including tax position, highlight the risk elements, brief on benefits and limitations, explain the options, summarise the reasons for recommending it, compare against the Basic Financial Planning Guide where applicable, explain the policy illustration (guaranteed and non-guaranteed benefits), disclose distribution costs and charges, and explain the 14-day free-look provision.', trap: 'The presentation starts with the purpose of the product - the need being met - not with the premium or the benefits.' },
      { id: 'r25-02', term: 'Communicate clearly and simply', fact: 'Explain products in language the client can comfortably understand and avoid technical jargon; where terms like surrender value or bonuses are unavoidable, explain them. LIA\'s \'Your Guide to Life Insurance\' provides a comprehensive list of insurance terms in simple language. Check the client\'s understanding as you go.', trap: 'Common insurance terms still need explaining; assuming the client knows what surrender value means defeats the purpose.' },
      { id: 'r25-03', term: 'Disclosure of material facts at closing', fact: 'When completing the proposal form, highlight the importance of disclosing all material facts. If either party is doubtful whether a fact is material, advise the client to disclose it, and warn that he or his beneficiaries might receive nothing under the policy if a material fact is not disclosed.', trap: 'When in doubt about materiality, disclose - the default is disclosure, not omission.' },
      { id: 'r25-04', term: 'LIA document sequence', fact: 'Under the LIA Guidelines for life insurance advisory, each prospective buyer must receive, in sequence: the Cover Page, the Policy Illustration, the Product Summary, and the Bundled Product Disclosure, together with \'Your Guide to Life Insurance\' and \'Your Guide to Health Insurance\' as applicable. The same sequence applies for accident and health insurance advisory.', trap: 'The Cover Page comes first in the prescribed sequence, followed by the Policy Illustration, then the Product Summary.' },
      { id: 'r25-05', term: 'Product Summary, PHS and Policy Illustration', fact: 'The Product Summary describes the features of the product being bought. The Product Highlights Sheet is provided for ILPs and describes the key features and risks of the ILP sub-fund. Insurers must by law reveal all costs and charges, including distribution costs covering the commission payable to the representative, and these are shown in the Policy Illustration.', trap: 'Distribution costs, including the representative\'s commission, appear in the Policy Illustration, not the Product Summary.' },
      { id: 'r25-06', term: 'Reference checklist and declining a sale', fact: 'At the point of sale, the client is given a reference checklist covering FAA-N03 information: general information about the representative and his status, remuneration, conflicts of interest, designated investment products, illustrations of past and future performance, and marketing materials. The client signs the checklist at the end of the sales advisory process. Where a client is not suitable to buy any financial product (e.g. fails the CKA and does not understand critical features), the right course is to decline the sale.', trap: 'The client, not the representative, signs the reference checklist to verify he received the required information.' },
    ],
  },
  {
    id: 'r26',
    num: 26,
    title: 'Reviewing Clients\' Portfolios',
    page: 853,
    concepts: [
      { id: 'r26-01', term: 'When to review: four general principles', fact: 'The timing and frequency of client reviews depend on four factors: the client\'s personal circumstances, external developments, the products purchased by the client, and product developments in the market.', trap: 'New product launches are themselves a legitimate trigger for a review, alongside changes in the client\'s own life.' },
      { id: 'r26-02', term: 'Personal, family and employment changes', fact: 'Reviews are prompted by personal changes (e.g. upgrading from an HDB flat to a condominium, deteriorating health), family changes (marriage, birth, death of a spouse, inheritance, divorce, caring for an elderly parent) and employment changes. For retirement or redundancy, the review should ideally take place just BEFORE the event so preparations can be made.', trap: 'The pre-retirement review happens before retirement or redundancy takes effect, not after.' },
      { id: 'r26-03', term: 'External developments', fact: 'External triggers for review include changes in CPF rules (e.g. a change in employee or employer contribution rates) and market changes such as a steep fall in equity prices, especially where the client or his ILP funds are heavily invested in equities.', trap: 'A market fall triggers a review of ILPs too, because the underlying funds may be equity-heavy.' },
      { id: 'r26-04', term: 'Product-driven reviews', fact: 'Life insurance products should be reviewed when conversion options exist (usually exercisable without further evidence of health), when the policy is written under trust (to keep beneficiaries current), and to check the sum assured remains sufficient. Health insurance should be reviewed at annual renewal and for adequacy of cover. ILPs should be reviewed for possible fund switches based on the fund performance report and policy statement.', trap: 'Life insurance conversion options can usually be exercised without fresh evidence of health - a valuable right that lapses if forgotten.' },
      { id: 'r26-05', term: 'Product developments', fact: 'New products create review opportunities: long-term care insurance offers protection against chronic ill health, and capital-guaranteed investment-linked policies may suit clients wanting to lock in returns while protecting the initial investment.', trap: 'Reviewing for new products must serve the client\'s needs; it is not a licence to replace policies for commission.' },
      { id: 'r26-06', term: 'Replacement of policies', fact: 'Replacement of insurance policies should normally be discouraged, and any replacement recommendation should be acknowledged and agreed by the representative\'s supervisor to mitigate unethical selling. Replacement re-sets the incontestability clause, the waiting period and the suicide clause, and the client loses the accumulated reversionary bonus of the replaced policy.', trap: 'Three clauses re-set on replacement (incontestability, waiting period, suicide clause) and accumulated reversionary bonuses are lost - replacement is rarely cost-free.' },
    ],
  },
  {
    id: 'r27',
    num: 27,
    title: 'Basic Financial Planning Guide',
    page: 860,
    concepts: [
      { id: 'r27-01', term: 'Launch of the Guide', fact: 'On 7 October 2023, MAS - together with the Association of Banks in Singapore (ABS), the Association of Financial Advisers Singapore (AFAS) and the Life Insurance Association (LIA) - launched the Basic Financial Planning Guide. It is publicly available on the MoneySense website, and from January 2024 comes in six customised formats for different life stages.', trap: 'The Guide was launched by MAS with ABS, AFAS and LIA - the CPF Board is not one of the launch partners.' },
      { id: 'r27-02', term: 'Four rules of thumb', fact: 'The Guide\'s rules of thumb: set aside at least 3 to 6 months\' of expenses for emergencies; obtain insurance protection of 9x annual income for death and TPD and 4x annual income for critical illness; spend at most 15% of income on insurance protection; and invest at least 10% of income for retirement and other financial goals.', trap: '15% is a maximum (spend at most) while 10% is a minimum (invest at least) - the directions are opposite.' },
      { id: 'r27-03', term: 'Emergency funds under the Guide', fact: 'Keep emergency funds in a combination of savings accounts and Singapore Savings Bonds, which are government-guaranteed and can be exited in any month without penalty. Do not put emergency funds in the stock market, and CPF funds cannot serve as emergency funds because their use is tied to retirement, healthcare and housing. Irregular income earners should hold 12 months of expenses, and high-interest debts such as credit card bills should be paid off first.', trap: 'CPF savings cannot be used as emergency funds; and SSBs qualify because they can be redeemed any month without penalty.' },
      { id: 'r27-04', term: 'Basis of the 9x and 4x multiples', fact: 'The coverage multiples come from LIA\'s Protection Gap Study: about 9x annual income is needed by dependants on death or permanent disability to cover expenses, clear debts and maintain lifestyle; and assuming a 5-year recovery period from a major illness before returning to work, about 4x annual income is needed for critical illness.', trap: 'The 4x critical illness figure assumes a 5-year recovery period before the insured returns to the workforce.' },
      { id: 'r27-05', term: 'National schemes: MediShield Life and CareShield Life', fact: 'MediShield Life covers all Singapore Citizens and PRs for large hospital bills and selected costly outpatient treatments (e.g. cancer treatment, dialysis), with premiums fully payable by MediSave. CareShield Life is the national long-term care insurance for those born in 1980 onwards, paying monthly support on severe disability - the inability to perform at least 3 of the 6 activities of daily living - with premiums fully payable by MediSave.', trap: 'CareShield Life covers cohorts born in 1980 onwards; older ElderShield policyholders may opt in if they have not developed severe disability.' },
      { id: 'r27-06', term: 'Regulatory status of the Guide', fact: 'Use of the Guide is not a regulatory requirement and there is no penalty for not adopting it, but MAS strongly encourages FA firms to incorporate it into their advisory process. Sharing the Guide before conducting the full fact-find is not a breach, because it is general advice; however, the full financial needs analysis must still be completed before any transaction.', trap: 'The Guide gives general advice only - a full FNA is still required before completing any transaction based on it.' },
      { id: 'r27-07', term: 'Legacy planning under the Guide', fact: 'Legacy planning means making a will (estate distribution instructions), a CPF nomination (distribution of CPF savings), a Lasting Power of Attorney (appointing trusted persons to decide on your behalf if you lose mental capacity) and an Advance Care Plan (wishes for future health and personal care).', trap: 'The Lasting Power of Attorney deals with decisions during lost mental capacity; the Advance Care Plan records health and personal care wishes - they are different instruments.' },
      { id: 'r27-08', term: 'Investing and retirement under the Guide', fact: 'For the short term, consider Singapore Savings Bonds, T-bills and fixed deposits; for the long term, CPF retirement top-ups, exchange traded funds and unit trusts. Cash top-ups to CPF Special/Retirement Accounts enjoy up to S$8,000 in tax relief (including top-ups to parents\' accounts). Those aged 55 or above can monetise property via the Silver Housing Bonus, the Lease Buyback Scheme, or renting out a room or the flat.', trap: 'The property monetisation options - Silver Housing Bonus, Lease Buyback Scheme and renting out - are aimed at those aged 55 and above.' },
    ],
  },
]
